CREATE TABLE `agent_prompt_versions` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `agent_name` varchar(50) NOT NULL,
  `instructions` longtext NOT NULL,
  `changed_by` int(11) DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `prompt_agent_date` (`agent_name`,`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci;

CREATE TABLE `agent_prompts` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `agent_name` varchar(50) NOT NULL,
  `label` varchar(100) NOT NULL DEFAULT '',
  `description` text DEFAULT NULL,
  `instructions` text NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `agent_name` (`agent_name`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci;

CREATE TABLE `ai_provider_connections` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `provider` varchar(40) NOT NULL,
  `label` varchar(100) NOT NULL,
  `model` varchar(120) DEFAULT NULL,
  `secret_ciphertext` longtext DEFAULT NULL,
  `monthly_credit` decimal(12,2) DEFAULT NULL,
  `unit_cost` decimal(12,6) DEFAULT NULL,
  `enabled` tinyint(4) NOT NULL DEFAULT 1,
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `provider` (`provider`)
) ENGINE=InnoDB AUTO_INCREMENT=503 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci;

