CREATE TABLE `analytics_schema_migrations` (
  `migration_key` varchar(100) NOT NULL,
  `applied_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`migration_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci;

INSERT INTO `analytics_schema_migrations` VALUES ('gsc_path_scope_v1','2026-09-11 01:09:36');
CREATE TABLE `api_usage_logs` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) DEFAULT NULL,
  `provider` varchar(50) NOT NULL,
  `action` varchar(50) DEFAULT NULL,
  `tokens_used` int(11) DEFAULT 0,
  `estimated_cost` decimal(12,6) NOT NULL DEFAULT 0.000000,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=235 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci;

