CREATE TABLE `monitor_alert_settings` (
  `id` tinyint(3) unsigned NOT NULL,
  `enabled` tinyint(1) NOT NULL DEFAULT 0,
  `smtp_host` varchar(255) DEFAULT NULL,
  `smtp_port` smallint(5) unsigned DEFAULT 587,
  `smtp_secure` varchar(10) DEFAULT 'tls',
  `smtp_user` varchar(255) DEFAULT NULL,
  `smtp_pass` varchar(255) DEFAULT NULL,
  `smtp_from_email` varchar(255) DEFAULT NULL,
  `smtp_from_name` varchar(255) DEFAULT 'Monitor',
  `alert_to` varchar(500) DEFAULT NULL,
  `cpu_warning_pct` smallint(6) DEFAULT 80,
  `cpu_critical_pct` smallint(6) DEFAULT 95,
  `mem_warning_pct` smallint(6) DEFAULT 85,
  `mem_critical_pct` smallint(6) DEFAULT 95,
  `disk_warning_pct` smallint(6) DEFAULT 90,
  `disk_critical_pct` smallint(6) DEFAULT 97,
  `last_state` varchar(20) DEFAULT NULL,
  `last_alert_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `alert_on_cpu` tinyint(1) NOT NULL DEFAULT 1,
  `alert_on_mem` tinyint(1) NOT NULL DEFAULT 1,
  `alert_on_disk` tinyint(1) NOT NULL DEFAULT 1,
  `alert_on_db` tinyint(1) NOT NULL DEFAULT 1,
  `alert_on_cron` tinyint(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci;

CREATE TABLE `posts` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `platform` varchar(50) NOT NULL,
  `platform_post_id` varchar(255) DEFAULT NULL,
  `raw_content` text DEFAULT NULL,
  `transcript` text DEFAULT NULL,
  `generated_title` varchar(255) DEFAULT NULL,
  `generated_body` longtext DEFAULT NULL,
  `generated_excerpt` text DEFAULT NULL,
  `edited_title` varchar(255) DEFAULT NULL,
  `edited_body` longtext DEFAULT NULL,
  `edited_excerpt` text DEFAULT NULL,
  `tags` text DEFAULT NULL,
  `meta_description` varchar(255) DEFAULT NULL,
  `media_url` text DEFAULT NULL,
  `media_type` varchar(50) DEFAULT NULL,
  `media_display_width` tinyint(3) unsigned DEFAULT NULL,
  `media_alignment` varchar(20) NOT NULL DEFAULT 'center',
  `noindex` tinyint(4) NOT NULL DEFAULT 0,
  `source_url` text DEFAULT NULL,
  `published_at` datetime DEFAULT NULL,
  `imported_at` datetime DEFAULT current_timestamp(),
  `content_hash` char(64) DEFAULT NULL,
  `relevance_score` int(11) DEFAULT 0,
  `agent_notes` text DEFAULT NULL,
  `seo_score` int(11) DEFAULT 0,
  `processing_status` varchar(20) NOT NULL DEFAULT 'pending',
  `processing_started_at` datetime DEFAULT NULL,
  `processing_attempts` int(11) NOT NULL DEFAULT 0,
  `processing_error` text DEFAULT NULL,
  `slug` varchar(255) DEFAULT NULL,
  `published` tinyint(4) DEFAULT 1,
  `featured` tinyint(4) DEFAULT 0,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_post` (`user_id`,`platform`,`platform_post_id`),
  CONSTRAINT `posts_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=71 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci;

INSERT INTO `posts` VALUES ('20','3','facebook','10234926491764819','A volte mi vergogno di essere chiamato \"uomo\". Mi spaventa anche soltanto immaginare che esista davvero  l\'inferno in terra. FAtto di paure, delusioni, sofferenza. Il senso di impotenza mi schiaccia, ogni volta che sento che un\'altra donna sia stata uccisa. Per questo ho composto questo brano. Non soltanto per celebrare le donne in quanto tali, ma per gridare a chi si reputa uomo; \"FERMATI TI PREGO\". Se almeno un uomo sentendo questo brano si fermerà, sarà un motivo in piu\' per dare senso alla mia vita.\nFonte elenco vittime: Osservatorio nazionale Femminicidi Lesbicidi Trans*cidi – Non Una Di Meno, dati aggiornati all’8 settembre 2026. \nMusiche Testi ed elaborazioni Video: Marco Mirra\nOrchestrazione e Mastering e i soggetti nel video sviluppati con Intelligenza Artificiale\nwww.marcomirra.it','','Un brano contro la violenza sulle donne: l\'impegno di Marco Mirra','<p>Il senso di impotenza di fronte alla violenza di genere e ai continui casi di femminicidio ha spinto il musicista <strong>Marco Mirra</strong> a comporre un nuovo brano musicale. L\'opera nasce dal profondo disagio e dalla sofferenza provati di fronte alle tragiche notizie di cronaca, proponendosi come un accorato appello al valore della vita e al rispetto.</p><h2>Un messaggio diretto e una richiesta di cambiamento</h2><p>Il progetto non si limita a celebrare la figura femminile, ma si rivolge direttamente al pubblico maschile con un messaggio chiaro e perentorio: \"FERMATI TI PREGO\". L\'obiettivo dell\'autore è sensibilizzare gli ascoltatori e stimolare una profonda riflessione individuale, sperando che la musica possa contribuire ad arrestare la spirale di violenza.</p><h2>Produzione musicale e tecnologie utilizzate</h2><p>Testi, musiche ed elaborazioni video sono stati interamente curati da Marco Mirra. Per la realizzazione dell\'opera, l\'autore si è avvalso del supporto dell\'<strong>Intelligenza Artificiale</strong>, utilizzata sia per la fase di orchestrazione e mastering sonoro, sia per lo sviluppo dei soggetti visivi presenti nel video ufficiale. Il contenuto fa riferimento ai dati sulle vittime raccolti dall\'Osservatorio nazionale Femminicidi Lesbicidi Trans*cidi – Non Una Di Meno. Per maggiori informazioni sul progetto è possibile consultare il sito ufficiale www.marcomirra.it.</p>','Marco Mirra presenta un brano musicale contro la violenza sulle donne, realizzato con il supporto dell\'IA per sensibilizzare il pubblico maschile.',NULL,NULL,NULL,'[\"Marco Mirra\",\"violenza sulle donne\",\"musica e sociale\",\"Intelligenza Artificiale\",\"sensibilizzazione\"]','Un brano musicale e un appello contro i femminicidi: il nuovo progetto di Marco Mirra realizzato con il supporto dell\'Intelligenza Artificiale.','','text',NULL,'center','0','https://www.facebook.com/twoemme/posts/pfbid02pGgeKhea2ixBnzK8QW1XYTZWapHqfsLQ8dKHgaKoyqyHFg4zB8ucYH1QLkG4qKo7l','2026-09-15 17:56:48','2026-09-19 09:15:05','4c2cbbf4814ef97a6770bf953ce4cd92ad058bcfb8207a360ef20a90a2707828','0','Approvato dal revisore editoriale: Brano musicale originale e messaggio di sensibilizzazione sul femminicidio; contenuto rilevante, espressivo e privo di duplicati.','85','done',NULL,'1',NULL,'un-brano-contro-la-violenza-sulle-donne-l-impegno-di-marco-mirra','1','0');
INSERT INTO `posts` VALUES ('21','3','facebook','10234334072674712','Storia triste, ma che rende orgogliosi di essere italiani!!','','Una storia d\'eccellenza e orgoglio italiano','<p>Esistono vicende che, pur nella loro complessità e carica emotiva, riescono a trasmettere un profondo senso di appartenenza e orgoglio nazionale. Sono storie che raccontano il valore, la resilienza e la passione tipiche del Made in Italy, capaci di toccare le corde più intime di chi le ascolta e di dimostrare quanto la nostra cultura e la nostra identità sappiano fare la differenza anche nei momenti più difficili.</p><h2>Il valore delle storie che ci uniscono</h2><p>Valorizzare queste esperienze significa riconoscere l\'impatto straordinario che le persone e le imprese italiane possono avere nel proprio settore. La capacità di trasformare le sfide in motivo di riscatto è un tratto distintivo che definisce da sempre l\'eccellenza del nostro Paese, offrendo spunti di riflessione fondamentali per chiunque cerchi ispirazione nel proprio percorso personale o professionale.</p><h2>L\'impegno per l\'eccellenza italiana</h2><p>Attraverso la condivisione di questi racconti, il nostro obiettivo è continuare a promuovere e sostenere i valori di qualità, dedizione e determinazione che rendono grande l\'Italia nel mondo. Crediamo fermamente che dare voce a queste realtà sia il modo migliore per ispirare la community e costruire un futuro basato sul merito e sull\'identità.</p><p>Vuoi scoprire come sosteniamo e valorizziamo le eccellenze del nostro territorio? <strong>Contattaci oggi stesso</strong> per maggiori informazioni sui nostri progetti e servizi.</p>','Una storia commovente che richiama i valori dell\'eccellenza e dell\'orgoglio italiano, dimostrando la forza del nostro Paese anche nelle sfide.',NULL,NULL,NULL,'[\"Orgoglio Italiano\",\"Made in Italy\",\"Eccellenza Italiana\",\"Storie di Riscatto\",\"Valori Italiani\"]','Scopri una storia toccante che celebra l\'orgoglio e l\'eccellenza italiana, dimostrando la resilienza e la passione che ci contraddistinguono.','','text',NULL,'center','0','https://www.facebook.com/twoemme/posts/pfbid02Qse3bMK47DCT7avYcczpxMQHjCScbfdq96msCFcBL1cCzZZtnhXy7aoo9q6dckGYl','2026-07-26 20:38:13','2026-09-19 09:15:05','5f59c59e524ba371c9df957fab19f2e9246c37f88c441f278548ec92b164219b','0','Respinto dal revisore editoriale: Il post è estremamente vago, privo di contesto informativo e di valore SEO, configurandosi come puro rumore.','78','done',NULL,'1',NULL,'una-storia-d-eccellenza-e-orgoglio-italiano','1','0');
INSERT INTO `posts` VALUES ('22','3','facebook','10234305585522551','Io mi domando è così utopistico pensare ad un posto in cui vivere senza la fogna umana in cui siamo obbligati a convivere? Eppure abbiamo tutti gli elementi che fanno pensare a chiari segni di evoluzione. Ma, continua ad esserci il marciume che vediamo. Diciamolo a livello di politiche sociali l\'Italia ha fallito. E quindi? Si è passati dall\'avere paura dell\'altezza a non voler neanche più salire su una scala. Scusate la metafora. A strumentalizzare tutto come mezzucci di marketing da quattro soldi per solleticare le coscienze o rinvigorire chissà quali ideali. Non vi siete resi conto che ci hanno resettato? La troppa consapevolezza è pericolosa. Meglio una pancia piena e una  testa vuota che viceversa. Abbiamo assolutamente perso ogni autoreferenzialità, ma l\'essere umano non può vivere senza. E quindi? Si accontenta di quello che offre la società e credetemi a me non piace!!!','','Fallimento delle politiche sociali e crisi della consapevolezza','<p>La società odierna si trova di fronte a una complessa crisi di valori e d\'identità, segnata dal visibile fallimento delle politiche sociali in Italia. Nonostante la presenza di chiari elementi che indicano un\'evoluzione formale, la realtà quotidiana mostra un forte degrado della convivenza civile e delle dinamiche collettive.</p><h2>Marketing morale e perdita di consapevolezza</h2><p>Un aspetto centrale di questo contesto è la strumentalizzazione delle istanze etiche, spesso ridotte a semplici strategie di marketing per solleticare le coscienze o rinverdire vecchi ideali. Questo meccanismo ha portato a una progressiva perdita di consapevolezza autonoma: si preferisce la stabilità materiale e la superficialità rispetto a un\'analisi critica della realtà, poiché una troppa consapevolezza viene percepita come un pericolo per l\'ordine costituito.</p><h2>La necessità di ritrovare un\'identità autonoma</h2><p>L\'essere umano non può vivere senza autoreferenzialità, eppure la tendenza attuale porta ad accontentarsi passivamente di ciò che offre la società. Superare questo reset culturale è fondamentale per ricostruire una visione critica e rifiutare le scorciatoie di una conformità di comodo, promuovendo un reale cambiamento sociale.</p>','Un\'analisi critica sul fallimento delle politiche sociali in Italia, tra strumentalizzazione del marketing ed esigenza di consapevolezza.',NULL,NULL,NULL,'[\"politiche sociali\",\"societ\\u00e0\",\"consapevolezza\",\"Italia\",\"riflessione sociale\"]','Analisi sul fallimento delle politiche sociali in Italia, la perdita di consapevolezza e il bisogno di ritrovare un\'identità critica e autonoma.','','text',NULL,'center','0','https://www.facebook.com/twoemme/posts/pfbid02FZ3pi9NegF1Lt5FerHf5c7sJ4Ftqm99EHndeML85RAEZKPJVv7oNtdYcKP8Z8wicl','2026-07-24 09:15:46','2026-09-19 09:15:05','e6a4bf4d2bc0bbe203088f2efe5c3c6b6a0c0d843a418cdf865c37d2d2c04d5d','0','Respinto dal revisore editoriale: Si tratta di uno sfogo personale e polemico privo di valore informativo o utilità SEO, classificabile come puro rumore.','82','done',NULL,'1',NULL,'fallimento-delle-politiche-sociali-e-crisi-della-consapevolezza','1','0');
INSERT INTO `posts` VALUES ('23','3','facebook','10233859573612532','Si può fare.. il prossimo progetto sarà integrazione totale teatro e tecnologia per strizzare anche l\'ultima di goccia di emozione che ogni artista non vuole tenersi per sé.. E intanto mi studio il Teatro Brancaccio','','Teatro e Tecnologia: Il Nuovo Progetto al Teatro Brancaccio','<p>L\'innovazione tecnologica incontra l\'arte scenica in una nuova visione di produzione teatrale. L\'obiettivo del nostro prossimo progetto è realizzare un\'<strong>integrazione totale tra teatro e tecnologia</strong>, uno strumento pensato per amplificare l\'impatto emotivo delle esibizioni e valorizzare al massimo l\'espressività degli artisti sul palco.</p><h2>L\'Analisi del Teatro Brancaccio</h2><p>Attualmente la fase di studio e ricerca è incentrata su una delle location più prestigiose della scena culturale: il <strong>Teatro Brancaccio</strong>. Attraverso l\'analisi delle caratteristiche strutturali e delle potenzialità di questo celebre spazio, stiamo progettando soluzioni tecnologiche capaci di catturare e trasmettere ogni singola sfumatura emozionale dello spettacolo.</p><h2>Un Nuovo Standard per la Spettacolarizzazione</h2><p>Questo connubio nasce dalla volontà di offrire alle produzioni e ai performer un supporto all\'avanguardia, in grado di estrarre e potenziare il potenziale comunicativo di ogni performance. La tecnologia non sostituisce l\'attore, ma ne diventa il cassa di risonanza visiva e sensoriale.</p><p>Siamo pronti a trasformare il modo di vivere la scena. <strong>Contattaci</strong> per scoprire come le nostre soluzioni tecnologiche possono valorizzare la tua prossima produzione teatrale.</p>','Integrazione tra teatro e tecnologia: al via lo studio sul Teatro Brancaccio per amplificare l\'emozione delle performance artistiche sul palco.',NULL,NULL,NULL,'[\"teatro e tecnologia\",\"Teatro Brancaccio\",\"innovazione teatrale\",\"produzioni teatrali\",\"spettacolo dal vivo\"]','Integrazione totale tra teatro e tecnologia: scopri il nuovo progetto di innovazione scenica focalizzato sullo studio del Teatro Brancaccio.','','text',NULL,'center','0','https://www.facebook.com/twoemme/posts/pfbid0i5AZbjxfGPw7vJBDzrhd9PFykhGQ8emfiffYYHbXUTRnjvuUw3QKTU1MnA3cNqUTl','2026-06-16 00:51:25','2026-09-19 09:25:30','6072847b6964f46b3b272fb073c3a86d5a3e08d988fa1b3a54aeeea45fe1aae5','0','Approvato dal revisore editoriale: Il post annuncia un nuovo progetto artistico incentrato sull\'integrazione tra teatro e tecnologia, coerente con il profilo creativo e tecnologico dell\'autore e privo di sovrapposizioni con i contenuti recenti.','85','done',NULL,'1',NULL,'teatro-e-tecnologia-il-nuovo-progetto-al-teatro-brancaccio','1','0');
INSERT INTO `posts` VALUES ('24','3','website','67208388da8260f3f91aae7e','Home - MARCOMIRRA.IT\n\nBlog tecnologico e non solo. Gli argomenti trattati ruotano attorno al mondo delle nuove tecnologie e quant\'altro impatti sulla qualità della vita in questo tempo.\n\nHome - MARCOMIRRA.IT MARCOMIRRA.IT AI Creative Technologist Facebook Youtube Tiktok marcomirra.it AI Creative Technologis Neural Network Header - Blog Non seguo“TREND”riconosco “PATTERN”mm Non seguo “TREND” riconosco “PATTERN” Produzione Letteraria Vibrazioni e Sonificazioni: Dalle vibrazioni invisibili alla melodia dei dati attraverso la sonificazione Leggi Tutto » Intelligenza Artificiale e tecnologie digitali – Anatomia di un cambiamento Leggi Tutto » Informatica negli studi clinici Leggi Tutto » DiversaMente Logico – Il libro Leggi Tutto » Novità sviluppo applicazioni SONIFICART.COM: Metodo deterministico per tradurre le immagini in suono Guarda e ascolta la gallery di: WWW.SONIFICART.COM Nel mondo digitale siamo abituati a considerare le immagini e i suoni come due mondi separati. Cosa succederebbe se una fotografia potesse essere “suonata” come uno spartito?È qui che entra in gioco SonificART un’applicazione WEB che utilizza algoritmi deterministici ed AI. – CONTINUA A LEGGERE Quando l’arte si ascolta: la mia sonificazione delle tavole anatomiche attribuite ad Antonio Canova Ci sono momenti in cui tecnologia, arte e ricerca scientifica riescono a incontrarsi in modo Leggi Tutto » Chat Control 1.0: chi scansiona le tue chat, cosa ha deciso l’Europa e dove stiamo andando Il 9 luglio 2026 il Parlamento Europeo ha approvato la proroga del regolamento temporaneo noto Leggi Tutto » Aiutare i nostri figli a pensare nell’era dell’IA: una lezione da Montessori Il 13 marzo 2025 il Parlamento Europeo ha messo un punto fermo su qualcosa che ci riguarda tutti, molto più Leggi Tutto » Lettera Enciclica MAGNIFICA HUMANITAS della serie: “piu’ chiaro di cosi!” L’intelligenza artificiale può essere uno strumento al servizio della persona, oppure rischia di diventare lo strumento attraverso cui la persona viene ridotta, controllata, sostituita? Leggi Tutto » Il “tarlo” dentro la macchina: cos’è davvero il bias? Per fortuna, non siamo più nel Far West digitale. Nel 2026 le chiacchiere stanno a zero: le leggi sono arrivate e fanno paura alle aziende che fanno le furbe. Leggi Tutto » Grief Tech – La nuova frontiera dei “Defunti Digitali” Il dolore per la perdita di una persona cara rappresenta da sempre uno dei momenti più intimi e personali dell’esperienza Leggi Tutto » Legge 132/2025: L’Italia detta le nuove regole per l’Intelligenza Artificiale Dal 10 ottobre 2025 entra ufficialmente in vigore la Legge n. 132 del 23 settembre 2025, la prima norma organica Leggi Tutto » Internet sicuro… ma per chi? L’Inghilterra obbliga i siti porno a controllare l’età. In Europa invece? Tutto libero. Negli ultimi anni governi e istituzioni parlano tanto di sicurezza online, ma tra il dire e il fare c’è sempre Leggi Tutto » Articoli e Approfondimenti Produzioni musicalie progetti multimediali Il brano “Equilibrio Precario” rappresenta una vera fusione tra tecnologia e comunicazione.La voce è stata generata con l’ausilio di un’IA a partire da un cantato dell’autore, mentre musica e orchestrazione sono state sviluppate utilizzando sonorità rielaborate da un’intelligenza artificiale, in grado di rendere gli strumenti campionati (in particolare gli archi) estremamente fedeli alle loro controparti analogiche. Il testo, interamente scritto dall’autore, racchiude un messaggio profondo: tra la consapevolezza della precarietà e l’invito a vivere la propria vita non solo accettando questo stato, ma anche trasformandolo in un valore aggiunto, per abitare pienamente il proprio “presente”. VAI AL VIDEOCLIP Novità sviluppo applicazioni SONIFICART.COM: Metodo deterministico per tradurre le immagini in suono Guarda e ascolta la gallery di: WWW.SONIFICART.COM Nel mondo digitale siamo abituati a considerare le immagini e i suoni come due mondi separati. Cosa succederebbe se una fotografia potesse essere “suonata” come uno spartito?È qui che entra in gioco SonificART un’applicazione WEB che utilizza algoritmi deterministici ed AI. – CONTINUA A LEGGERE Progetti COMING SOON AI Sonic Mixer Leggi Tutto » LEO (Linguaggio.Espressione.Oralità) – L’applicazione che sfrutta ‘Intelligenza Artificiale per aiutare i bambini con disturbo alla comunicazione Leggi Tutto » Una redazione automatica personale basata sull’Intelligenza Artificiale. Leggi Tutto » SonificART: Metodo deterministico per tradurre le immagini in suono Leggi Tutto »','L\'immagine mostra un primo piano ravvicinato e angolato di un uomo maturo, ripreso in uno scatto dallo stile spontaneo e informale. Il soggetto indossa un paio di occhiali da vista con montatura trasparente, ha capelli castani brizzolati leggermente scompigliati e una barba corta nei toni del grigio e del biondo scuro. La sua espressione è seria, pensierosa e leggermente stanca, con uno sguardo diretto e penetrante rivolto verso l\'obiettivo. L\'inquadratura, volutamente inclinata (a \"angolo olandese\"), crea un senso di immediatezza e prossimità. Per quanto riguarda l\'abbigliamento, l\'uomo indossa una giacca o un maglione grigio-nocciola con lavorazione a costine e cerniera a vista, sovrapposto a un capo scuro. Lo sfondo è sobrio e sfocato, caratterizzato da pannelli dalle tonalità fredde del grigio e dell\'azzurro, che creano un contrasto cromatico capace di far risaltare i toni caldi dell\'incarnato.\n\nNell\'immagine non è presente alcun testo scritto, infografica o elemento grafico sovrapposto.\n\nDal punto di vista emotivo e comunicativo, lo scatto trasmette un forte senso di autenticità, trasparenza e realismo. L\'assenza di filtri o di pose artificiose comunica vulnerabilità e maturità, invitando chi osserva a una connessione empatica e profonda. A livello commerciale o narrativo, un\'immagine di questo tipo si presta perfettamente come simbolo di vita reale, introspezione e genuinità. È uno scatto ideale per accompagnare contenuti che parlano di salute mentale, bilancio di vita, lavoro freelance, sfide della maturità o storie personali che mettono al centro la verità dell\'essere umano senza sovrastrutture.','SonificART: come tradurre le immagini in suono con l\'AI','<p>Nel panorama delle nuove tecnologie digitali, l\'intersezione tra arte visiva e musica sta aprendo frontiere inesplorate. Con l\'applicazione web <strong>SonificART</strong>, creata da Marco Mirra (AI Creative Technologist), immagini e suoni smettono di essere due ambiti distinti. Attraverso l\'uso di algoritmi deterministici e intelligenza artificiale, la piattaforma consente di trasformare una fotografia o un\'opera visiva in una vera e propria struttura sonora.</p><h2>Dal dato visivo alla composizione musicale</h2><p>Il metodo sviluppato alla base di SonificART supera la semplice interpretazione casuale: applica un processo deterministico che traduce i dati dell\'immagine in parametri musicali precisi. Un esempio concreto di questa tecnologia è la sonificazione delle tavole anatomiche attribuite ad Antonio Canova, dove la ricerca scientifica e l\'arte classica incontrano l\'algoritmo per dar vita a un\'esperienza d\'ascolto inedita.</p><h2>Sperimentazione e creatività multidisciplinare</h2><p>L\'approccio non segue semplicemente i trend del momento, ma analizza i pattern per integrare tecnologia, sensibilità artistica e comunicazione. Dalle produzioni multimediali ai progetti dedicati all\'accessibilità e al linguaggio, la sonificazione dimostra come l\'IA possa diventare un potente strumento espressivo al servizio della cultura e dell\'innovazione. Visita il sito per scoprire la gallery e ascoltare le sonificazioni.</p>','Scopri SonificART, l\'applicazione web che utilizza algoritmi deterministici e IA per trasformare le immagini in composizioni sonore originali.',NULL,NULL,NULL,'[\"SonificART\",\"Intelligenza Artificiale\",\"Sonificazione\",\"Marco Mirra\",\"Arte Digitale\"]','SonificART è l\'applicazione che traduce immagini e fotografie in suono tramite algoritmi deterministici e intelligenza artificiale. Scopri il progetto.','https://allsocialtoweb.com/public/media/website_67208388da8260f3f91aae7e.png','image',NULL,'center','0','https://www.marcomirra.it','2026-09-19 09:31:03','2026-09-19 09:31:03','ba99dcc13084c33bf65246bf73dd9804ffa590f4f9b255f73629b6ab007caf70','0','Approvato dal revisore editoriale: Il contenuto definisce in modo chiaro la missione e la figura di Marco Mirra come AI Creative Technologist e presenta progetti innovativi come SonificART.','88','done',NULL,'1',NULL,'sonificart-come-tradurre-le-immagini-in-suono-con-l-ai','1','1');
INSERT INTO `posts` VALUES ('25','3','facebook','10233823056339623','Ok lo dico. Mi candido a Sindaco di Roma..per iniziare poi si vedrà!!!','','Candidatura a Sindaco di Roma: Provocazione e Innovazione','<p>L\'annuncio è arrivato in modo diretto e spiazzante sui canali social: <strong>&quot;Ok lo dico. Mi candido a Sindaco di Roma..per iniziare poi si vedrà!!!&quot;</strong>. Una dichiarazione che unisce la forza della provocazione alla volontà di scuotere il dibattito pubblico sulla gestione e sul futuro della Capitale.</p><h2>L\'impatto della dichiarazione e la visione per il futuro</h2><p>Questa candidatura rappresenta un punto di partenza strategico per lanciare una riflessione più ampia sulle dinamiche urbane, sociali e culturali della città. In un\'epoca in cui l\'innovazione tecnologica e le nuove forme artistiche stanno ridefinendo i processi partecipativi, l\'affermazione si pone come uno stimolo a pensare il contesto cittadino oltre i classici schemi della politica tradizionale.</p><h2>Unire tecnologia, cultura e impegno civico</h2><p>L\'obiettivo di questo annuncio non è solo una sfida elettorale, ma l\'avvio di un percorso aperto al confronto. Integrare linguaggi innovativi, come l\'intelligenza artificiale e la progettazione culturale, all\'interno dello spazio pubblico è la chiave per costruire nuove opportunità di riscatto e sviluppo sociale per Roma e i suoi cittadini.</p><p>Vuoi rimanere aggiornato sui prossimi sviluppi di questo progetto e sulle iniziative culturali e tecnologiche in programma? Contattaci o iscriviti alla newsletter per partecipare attivamente al dibattito.</p>','L\'annuncio della candidatura a Sindaco di Roma: un\'iniziativa tra provocazione, innovazione e riflessione sul futuro della Capitale.',NULL,NULL,NULL,'[\"Roma\",\"Candidatura Sindaco\",\"Innovazione\",\"Cultura\",\"Impegno Civico\"]','Scopri i dettagli e il significato dell\'annuncio sulla candidatura a Sindaco di Roma e le prospettive di innovazione per la città.','','text',NULL,'center','0','https://www.facebook.com/twoemme/posts/pfbid0TLvZJURXZWRTjWbq2st4xJZoHs92Zcm6yhUnddNhYLNx4TDJPX2cpHA51eWHajdHl','2026-06-12 21:37:08','2026-09-19 11:40:04','f6bbd9b481b8a495a685bcd0fe425e36bbc0cf24090e659392fe8e19d6dd80f7','0','Respinto dal revisore editoriale: Post d\'opinione/battuta social privo di valore editoriale, non pertinente con la missione legata a IA, teatro e arte digitale.','80','done',NULL,'1',NULL,'candidatura-a-sindaco-di-roma-provocazione-e-innovazione','0','0');
INSERT INTO `posts` VALUES ('26','3','facebook','10233821237174145','Io ho capito una cosa sola: come nazione rischiamo seriamente di diventare lo zimbello del mondo.\n\nE questo, a mio avviso, non dipende solo dai singoli personaggi politici o dalle loro uscite televisive. Dipende da qualcosa di più profondo: da una deriva culturale e morale che da tempo sta consumando i valori fondamentali della persona, della comunità e della responsabilità.\n\nSi parla spesso di apertura mentale, di progresso, di modernità. Ma troppo spesso questa presunta apertura si traduce in confusione, relativismo e incapacità di distinguere ciò che costruisce da ciò che distrugge. Abbiamo smesso di chiederci cosa sia giusto e cosa sia sbagliato, cosa faccia bene e cosa faccia male, cosa rafforzi una società e cosa invece la renda più fragile.\n\nIo, per valutare la politica, faccio un ragionamento molto semplice: metto su carta alcune priorità concrete e mi chiedo chi abbia davvero il coraggio di affrontarle. La sicurezza, la tutela della vita, il sostegno a chi lavora, il contrasto all’assistenzialismo improduttivo, la difesa delle persone più fragili, il bisogno di vivere in una società più ordinata, più giusta e più umana.\n\nNon mi interessano più gli slogan, le etichette, le appartenenze o le pose morali. Mi interessa capire chi sia davvero capace di dare risposte concrete a un Paese disorientato, stanco, spesso abbandonato a se stesso.\n\nIl problema è che da troppo tempo si è lavorato, più o meno consapevolmente, per sradicare le basi su cui una comunità dovrebbe reggersi. Sono state denigrate le nostre radici, anche quelle cristiane, senza sostituirle con qualcosa di altrettanto solido. Ma la natura ce lo insegna: nulla resta in piedi davanti alla forza del vento se non è ben saldo nella terra.\n\nE mentre noi ci distraiamo, ci dividiamo, ci facciamo addormentare dal rumore continuo dell’intrattenimento, dello sport, delle polemiche e delle sciocchezze quotidiane, altre radici crescono in silenzio sotto la superficie, togliendo sostanza a ciò che resta della nostra terra comune.\n\nBen venga allora qualunque rappresentante politico, di qualsiasi area o provenienza, se sarà capace di creare i presupposti per vivere in una società più giusta, più responsabile e davvero a misura d’uomo.\n\nPerché il punto non è più difendere una bandiera. Il punto è capire se vogliamo ancora difendere una civiltà.','','Deriva culturale e valori: una riflessione sulla società','<p>La società contemporanea si trova ad affrontare una profonda crisi identitaria, caratterizzata da un progressivo smarrimento dei valori fondamentali di comunità e responsabilità. Sempre più spesso, la promessa di modernità e progresso si traduce in un relativismo che rende difficile distinguere ciò che edifica da ciò che indebolisce la struttura sociale.</p><h2>Oltre le etichette: concretezza e radici</h2><p>Per valutare il panorama politico attuale occorre superare la logica degli slogan e focalizzarsi su priorità tangibili: sicurezza, dignità del lavoro, tutela dei più fragili e contrasto all\'assistenzialismo. Il rischio di sradicare la nostra storia e le nostre radici culturali e cristiane lascia un vuoto rischioso, soprattutto di fronte alle sfide del nostro tempo.</p><h2>Per una nuova responsabilità collettiva</h2><p>Mentre la sfera pubblica appare distratta da polemiche quotidiane e dall\'intrattenimento continuo, si avverte la necessità di ritrovare la coesione. L\'obiettivo primario non è schierarsi dietro un simbolo o una fazione, ma collaborare con chiunque dimostri la capacità concreta di ricostruire una società equa, responsabile e a misura d\'uomo.</p>','Una riflessione sulla deriva culturale attuale e sulla necessità di riscoprire valori e priorità concrete per ricostruire il senso di comunità.',NULL,NULL,NULL,'[\"cultura\",\"societ\\u00e0\",\"valori\",\"responsabilit\\u00e0\",\"politica\"]','Analisi sulla crisi culturale moderna e sull\'importanza di ritrovare radici e risposte concrete per la comunità.','','text',NULL,'center','0','https://www.facebook.com/twoemme/posts/pfbid0Ao5PqE4L7yJbapyKbB373TNc5yiHmhGFkcKPF3t9W9LNJUpM4AA4xDju2wvuUY5Dl','2026-06-12 18:24:11','2026-09-19 11:40:04','369176ebed6c1a0fa509a79f9dc002d13f70a4f29428500b951e9c3524f76e93','0','Respinto dal revisore editoriale: Si tratta di uno sfogo politico-sociale generico privo di collegamenti con l\'IA, il teatro o la tecnologia creativa, configurandosi come puro rumore rispetto alla missione del brand.','82','done',NULL,'1',NULL,'deriva-culturale-e-valori-una-riflessione-sulla-societa','0','0');
INSERT INTO `posts` VALUES ('27','3','facebook','10233762739071729','E se poi alla fine questa è una delle strade?','','Intelligenza Artificiale e Teatro: Nuove Strade Espressive','<p>L\'intersezione tra innovazione tecnologica e arte drammatica sta aprendo scenari inediti per la narrazione contemporanea. L\'utilizzo dell\'<strong>Intelligenza Artificiale nelle produzioni teatrali</strong> non rappresenta soltanto una sperimentazione tecnica, ma una vera e propria risorsa artistica per esplorare nuove forme di sensibilità sociale e storie di riscatto.</p><h2>Un linguaggio integrato per la scena</h2><p>Integrare l\'IA sul palcoscenico significa ampliare le possibilità creative dei performer e dei registi. Questa convergenza permette di connettere l\'ambito digitale con il profondo valore umano tipico dell\'esperienza teatrale dal vivo, offrendo al pubblico chiavi di lettura innovative e altamente coinvolgenti.</p><h2>Sperimentazione e valore sociale</h2><p>La ricerca di nuovi percorsi espressivi dimostra come la tecnologia possa diventare uno strumento al servizio dell\'inclusione e del riscatto personale. Proseguire lungo questa strada significa guidare l\'evoluzione del settore dello spettacolo verso un futuro in cui etica, arte e algoritmo collaborano per creare valore culturale duraturo.</p>','L\'integrazione tra Intelligenza Artificiale e teatro apre nuove strade espressive e sociali per il settore dello spettacolo.',NULL,NULL,NULL,'[\"Intelligenza Artificiale\",\"Teatro\",\"Innovazione Digitale\",\"Arte e Tecnologia\",\"Produzioni Teatrali\"]','Scopri come la convergenza tra Intelligenza Artificiale e teatro apre nuove strade espressive per connettere arte digitale e valore umano.','','text',NULL,'center','0','https://www.facebook.com/twoemme/posts/pfbid0WTEKkK8Y8vZ4sJY7AkqDkA6dznh2ALkwZrCgoqCfQwbpn92BVTWBT5WzjDiHjPqvl','2026-06-07 15:03:04','2026-09-19 11:40:04','a7970d23499a1c27ca28c59d7451c4375b330333f91d5239f0801f9b21cbfec7','0','Respinto dal revisore editoriale: Il contenuto è una frase vaga e decontestualizzata, priva di valore informativo, approfondimento o chiaro legame con la missione (IA, teatro, valore umano). Risulta puro rumore social non idoneo per il sito.','80','done',NULL,'1',NULL,'intelligenza-artificiale-e-teatro-nuove-strade-espressive','0','0');
INSERT INTO `posts` VALUES ('28','3','facebook','10233697198273250','Ringrazio L\'Associazione Nazionale Famiglie numerose (https://www.facebook.com/ANFN.ITALY/?locale=it_IT) per averci invitato. Si è creao un mix strano tra esperienze di via vissuta come genitori di 4 figli e aiuto che spero possa aver dato a far capire cosa sta accadendo con l\'AI. Entro l\'anno (spoilerata) esce il nuovo libro. Non il solito malloppone tecnico o di retorica inutile, ma spero come strumento di riflessione ed azione per tutelare noi e le genrazioni future.','','IA e Famiglia: Incontro con l\'Associazione Famiglie Numerose','<p>Di recente ho avuto il piacere di partecipare a un incontro promosso dall\'<strong>Associazione Nazionale Famiglie Numerose</strong>. È stata un\'occasione preziosa per condividere riflessioni sul legame tra vita quotidiana, genitorialità e le nuove sfide poste dall\'<strong>Intelligenza Artificiale</strong>.</p><h2>Genitorialità e tecnologia: un\'esperienza condivisa</h2><p>Portando la mia esperienza sul campo come genitore di quattro figli, ho cercato di offrire spunti pratici per comprendere meglio i cambiamenti tecnologici in atto. L\'obiettivo dell\'intervento è stato quello di far chiarezza su cosa sta accadendo con l\'IA, integrando la vita vissuta con la consapevolezza digitale necessaria per orientarsi oggi.</p><h2>Un nuovo libro in arrivo entro l\'anno</h2><p>Durante l\'evento ho annunciato l\'uscita del mio <strong>nuovo libro</strong>, prevista entro la fine dell\'anno. Non si tratterà di un manuale tecnico o di un testo teorico, ma di uno <strong>strumento di riflessione e azione</strong> pensato per tutelare noi e le generazioni future nel contesto della trasformazione digitale.</p>','Resoconto dell\'intervento con l\'Associazione Nazionale Famiglie Numerose sull\'IA e annuncio del nuovo libro per orientare le generazioni future.',NULL,NULL,NULL,'[\"Intelligenza Artificiale\",\"Famiglie Numerose\",\"Libro IA\",\"Educazione Digitale\",\"Genitorialit\\u00e0\"]','Incontro con l\'Associazione Nazionale Famiglie Numerose su IA e futuro: riflessioni di vita vissuta e l\'annuncio del nuovo libro in uscita.','','text',NULL,'center','0','https://www.facebook.com/twoemme/posts/pfbid0fjbNtriK3zg3LaehB97X5END9q7C1xtBnPadibYEZkKHuQqZhm7FntCEZJHQnaBl','2026-06-01 17:56:21','2026-09-19 11:40:04','25db35b84c8c40e147a4590bac9ca069626f83052133027cfcd174aca41e5ce5','0','Approvato dal revisore editoriale: Il post coniuga l\'impatto dell\'IA sulla società e sulla famiglia con l\'annuncio di una nuova pubblicazione, perfettamente coerente con la missione di connettere tecnologia e valore umano.','85','done',NULL,'1',NULL,'ia-e-famiglia-incontro-con-l-associazione-famiglie-numerose','1','0');
INSERT INTO `posts` VALUES ('29','3','facebook','10233652154787191','È finita la pantomima in bermuda mascherata da cattolici! \nhttps://amp.tgcom24.mediaset.it/tgcom24/article/112625171\n\nLa decisione AGESCI di stabilire che orientamento sessuale e identità di genere non possano essere criteri di esclusione per ruoli educativi apre una questione seria: che cosa significa oggi definirsi associazione cattolica?\n\nIl punto non è l’accoglienza delle persone, che per un cristiano è doverosa e non negoziabile. Il punto è un altro: si può adottare il linguaggio dell’ideologia gender e continuare a presentarsi come realtà educativa pienamente coerente con il Magistero della Chiesa?\n\nPapa Leone XIV ha ribadito che la Chiesa resta aperta a tutti, ma che la dottrina su sessualità e matrimonio non cambia. Anche la Dignitas Infinita richiama con chiarezza il rischio di oscurare la differenza tra uomo e donna.\n\nPer questo la scelta AGESCI non può essere liquidata come semplice “svolta storica”. È una decisione che tocca l’identità stessa dell’associazione, soprattutto perché riguarda educatori e ragazzi.\n\nAccogliere ogni persona è cristiano. Assumere categorie ideologiche in contrasto con l’antropologia cattolica è un’altra cosa.\n\nSe un’associazione si definisce cattolica, deve avere il coraggio della coerenza. Altrimenti il rischio è mantenere il nome, ma svuotarne il significato.','','Agesci e ruoli educativi: la sfida della coerenza cattolica','<p>La recente decisione dell\'<strong>AGESCI</strong> di stabilire che l\'orientamento sessuale e l\'identità di genere non costituiscano criteri di esclusione per i ruoli educativi ha riaperto un dibattito fondamentale sul significato di associazione cattolica oggi. Sebbene l\'accoglienza di ogni persona sia un principio cristiano doveroso e non negoziabile, la scelta pone interrogativi complessi sulla coerenza con l\'antropologia e il Magistero della Chiesa.</p><h2>Accoglienza e coerenza con la dottrina</h2><p>Come ricordato dai richiami del Magistero e da documenti come la <em>Dignitas Infinita</em>, la Chiesa ribadisce l\'apertura verso tutti, mantenendo salda la dottrina su sessualità e matrimonio e sottolineando la centralità della differenza tra uomo e donna. La decisione dell\'associazione scout rileva quindi una tensione tra l\'adozione di determinate categorie concettuali e la conservazione dell\'identità educativa originale, destinata a guidare ed educare i ragazzi.</p><h2>L\'impatto sulla missione educativa</h2><p>Non si tratta di una semplice svolta storica, ma di una scelta che tocca la natura stessa delle realtà educative d\'ispirazione cristiana. Assumere un linguaggio in potenziale contrasto con la visione antropologica cattolica rischia di svuotare di significato l\'identità dell\'associazione stessa. Per mantenere un impatto sociale ed educativo autentico, resta indispensabile coniugare l\'apertura e il rispetto della persona con la chiarezza dei propri valori fondanti.</p>','La decisione AGESCI sui ruoli educativi apre il dibattito sulla coerenza tra accoglienza ed identità cattolica rispetto al Magistero della Chiesa.',NULL,NULL,NULL,'[\"AGESCI\",\"educazione\",\"Magistero\",\"identit\\u00e0 cattolica\",\"valori\"]','AGESCI e la svolta sui ruoli educativi: un\'analisi sulla coerenza tra accoglienza, identità cattolica e principi del Magistero.','','text',NULL,'center','0','https://www.facebook.com/twoemme/posts/pfbid0yzY8eXtEUFf7wfBQTmg4HmtXuZe5wnNHcfyJSEiTRjG5odFwhi11V8CRVKuQA1ZLl','2026-05-28 18:24:35','2026-09-19 11:40:04','9d74e673cc1426a68c9401fcc7abdf1ac8045c248f720de585b8ef032d97c5d8','0','Respinto dal revisore editoriale: Il post riguarda una polemica religioso-associativa su AGESCI e dottrina cattolica, priva di connessioni con Intelligenza Artificiale, teatro, arte digitale o innovazione tecnologica, risultando fuori target rispetto alla missione del sito.','85','done',NULL,'1',NULL,'agesci-e-ruoli-educativi-la-sfida-della-coerenza-cattolica','0','0');
INSERT INTO `posts` VALUES ('30','3','facebook','10233630051514623','E\' un po lungo come articolo.. ma efficace.','','Intelligenza Artificiale e Teatro: L\'Innovazione Digitale','<p>L\'integrazione tra <strong>Intelligenza Artificiale</strong> e produzioni teatrali rappresenta una nuova frontiera per il settore culturale e creativo. Coniugare le tecnologie emergenti con la sensibilità sociale consente di dare forma a narrazioni innovative, capaci di promuovere storie di riscatto e di impatto umano.</p><h2>L\'IA al Servizio dell\'Arte Scenica</h2><p>L\'uso degli strumenti digitali nel contesto teatrale non sostituisce la presenza umana, ma ne amplifica il valore espressivo. Attraverso l\'elaborazione di contenuti visivi, sonori e drammaturgici guidati dall\'IA, le produzioni artistiche riescono a raggiungere un pubblico più ampio, offrendo esperienze immersive ed efficaci.</p><h2>Valore Sociale e Opportunità per il Brand</h2><p>Innovare attraverso la convergenza tra tecnologia e teatro significa offrire alle aziende e alle realtà culturali nuove opportunità di comunicazione e coinvolgimento. Un approccio strategico che unisce arte e innovazione digitale permette di costruire progetti editoriali e di brand awareness capaci di generare un reale valore sociale.</p><p>Vuoi integrare le nuove tecnologie nella tua strategia di comunicazione aziendale o culturale? <strong>Contattaci</strong> per scoprire come sviluppare progetti innovativi basati sull\'IA.</p>','Scopri come la convergenza tra Intelligenza Artificiale e teatro crea innovazione digitale e storie di riscatto ad alto impatto sociale.',NULL,NULL,NULL,'[\"Intelligenza Artificiale\",\"Teatro Digitale\",\"Innovazione Culturale\",\"Arte e Tecnologia\",\"Brand Awareness\"]','Scopri come l\'Intelligenza Artificiale e il teatro si integrano per creare narrazioni innovative ed efficaci per la comunicazione culturale e aziendale.','','text',NULL,'center','0','https://www.facebook.com/twoemme/posts/pfbid02ksLmbUqpTtbHRcCMarJotF3nj7GUgf3vouj8kGgdY2F3wbA8PnHHv6DKvFhp7q2Wl','2026-05-26 19:28:17','2026-09-19 11:40:04','f4f94f88cda21c152bcc0a8e9f3eee1516899ab1adcbab7fa125bd08adb43c64','0','Respinto dal revisore editoriale: Il testo è privo di contesto, sostanza e argomentazione; si tratta di un breve commento generico che costituisce puro rumore e non aggiunge alcun valore al sito né intercetta la missione editoriale.','85','done',NULL,'1',NULL,'intelligenza-artificiale-e-teatro-l-innovazione-digitale','0','0');
INSERT INTO `posts` VALUES ('31','3','facebook','10233228077665528','E\' bello condividere la propria esperienza alle future generazioni! https://www.facebook.com/share/v/1FJ1hdycby/','','Condividere l\'esperienza con le future generazioni','<p>La trasmissione del sapere e delle competenze verso le nuove generazioni rappresenta un ponte fondamentale per connettere l\'innovazione digitale con il valore umano. Condividere la propria esperienza professionale e artistica significa offrire ai giovani strumenti concreti per interpretare il futuro, integrando tecnologie emergenti come l\'Intelligenza Artificiale con le arti narrative e performative.</p><h2>Il valore della testimonianza per i giovani</h2><p>Incontrare le future generazioni e raccontare il percorso sul campo permette di ispirare nuovi percorsi creativi e professionali. Il confronto diretto aiuta a comprendere come la convergenza tra tecnologia, teatro e sensibilità sociale possa diventare una leva di riscatto e crescita per la comunità intera.</p><h2>Costruire opportunità attraverso la formazione</h2><p>Attraverso momenti di scambio ed esperienze condivise, il dialogo con i giovani si trasforma in un\'opportunità di orientamento. L\'obiettivo è stimolare una visione critica e consapevole nell\'uso delle nuove tecnologie, ponendo sempre al centro l\'umanità e la capacità di raccontare storie significative.</p>','L\'importanza di condividere esperienze e competenze con le nuove generazioni per unire innovazione digitale, creatività e valore umano.',NULL,NULL,NULL,'[\"Formazione\",\"Future Generazioni\",\"Innovazione\",\"Intelligenza Artificiale\",\"Valore Umano\"]','Scopri il valore della condivisione dell\'esperienza con le future generazioni tra innovazione digitale, teatro e impatto sociale.','','text',NULL,'center','0','https://www.facebook.com/twoemme/posts/pfbid02oZHzEtbzBBNYf2DTAZsuHno8eC4gJNKyYiAZBoUK8L8jboGnYEWjkTVr2uasT3K2l','2026-04-21 15:57:01','2026-09-19 11:40:04','6b8d956a05b4001f66972504027ffca2e045bbf08f4db25d058bf3c8ede79287','0','Respinto dal revisore editoriale: Il post è estremamente generico e privo di contesto o approfondimento testuale; senza spiegazione del video, risulta di scarsa utilità per il sito e per la SEO.','80','done',NULL,'1',NULL,'condividere-l-esperienza-con-le-future-generazioni','0','0');
INSERT INTO `posts` VALUES ('32','3','facebook','10232906862755356','Questa volta lo ammetto non sapevo cosa votare. Ho cercato di avere un atteggiamento politicamente asettico, ma se sono vere queste immagini forse era meglio che andavo a votare...','','IA e immagini virali: l\'impatto della manipolazione visiva','<p>L\'esplosione dei contenuti visivi generati dall\'Intelligenza Artificiale sta trasformando radicalmente il modo in cui percepiamo la realtà e la politica. Di fronte ad immagini sempre più realistiche ma potenzialmente fuorvianti, anche l\'elettore più cauto o disinteressato si trova disorientato di fronte alla scelta di esprimere il proprio voto.</p><h2>L\'impatto delle immagini digitali sul dibattito pubblico</h2><p>Quando i confini tra ciò che è reale e ciò che è artificiale si assottigliano, l\'opinione pubblica rischia di essere condizionata da contenuti visivi non verificati. Immagini d\'impatto, condivise sui social media, possono mettere in discussione anche la decisione di astenersi dal voto, stimolando reazioni emotive immediate piuttosto che riflessioni basate su fatti concreti.</p><h2>Consapevolezza digitale e responsabilità sociale</h2><p>In un\'epoca in cui l\'IA può creare o alterare la narrazione pubblica, sviluppare un pensiero critico diventa fondamentale. Unire sensibilità sociale, tecnologia e arte digitale è la chiave per analizzare criticamente questi fenomeni, promuovendo un uso etico degli strumenti tecnologici al servizio di una cittadinanza consapevole.</p>','L\'impatto delle immagini generate con l\'IA sull\'opinione pubblica e sul voto: l\'importanza del pensiero critico di fronte alla manipolazione visiva.',NULL,NULL,NULL,'[\"Intelligenza Artificiale\",\"IA e Politica\",\"Consapevolezza Digitale\",\"Immagini AI\",\"Etica Digitale\"]','Come le immagini create con l\'IA influenzano la percezione politica e l\'astensionismo. Analisi sull\'impatto della tecnologia nella società attuale.','','text',NULL,'center','0','https://www.facebook.com/twoemme/posts/pfbid02ZZKK649dkLGsbb5wfHFLAhB1xinPA9eLmtEyKv5yNR9weWwFNMqc2HHbUkLGMuB4l','2026-03-24 19:50:53','2026-09-19 11:40:04','3ccfe75956a90ffa03e98bc369ad0acbfbf7f13a4510c9a315f7c73424c98d51','0','Respinto dal revisore editoriale: Il contenuto è un breve commento personale legato alla politica/elezioni, privo di approfondimento tecnico, artistico o di utilità per il target del sito.','80','done',NULL,'1',NULL,'ia-e-immagini-virali-l-impatto-della-manipolazione-visiva','0','0');
INSERT INTO `posts` VALUES ('33','3','facebook','10232505507121716','Condivido pienamente. Basta retorica...!!!!','','IA e Teatro: Superare la Retorica per Creare Valore Reale','<p>Nel panorama dell\'innovazione tecnologica e delle produzioni teatrali, la tentazione di rifugiarsi in slogan ad effetto o in una narrazione puramente retorica è sempre presente. Tuttavia, il vero cambiamento sociale e artistico si misura unicamente sull\'impatto concreto e sulla capacità di raccontare storie autentiche di riscatto.</p><h2>L\'integrazione tra Intelligenza Artificiale e Arte Digitale</h2><p>Quando l\'Intelligenza Artificiale incontra la sensibilità della scena teatrale, l\'obiettivo non deve essere il semplice stupore tecnologico. È fondamentale porre al centro il <strong>valore umano</strong>, utilizzando gli strumenti digitali per amplificare le emozioni e dare voce a storie profonde, superando la superficie delle tendenze del momento.</p><h2>Azioni Concrete oltre le Parole</h2><p>Superare le formule di circostanza significa costruire progetti concreti, in cui la convergenza tra tecnologia e teatro si traduce in opportunità reali per le persone e le comunità. Le linee guida per un approccio davvero efficace comprendono:</p><ul><li><strong>Autenticità della narrazione:</strong> Raccontare storie vere, evitando trionfalismi e semplificazioni prive di sostanza.</li><li><strong>Innovazione Responsabile:</strong> Impiegare l\'IA come strumento al servizio dell\'espressione artistica e dell\'inclusione.</li><li><strong>Impatto Sociale:</strong> Generare un valore tangibile nel settore delle arti performative e per il pubblico.</li></ul><p>Contattaci per scoprire i nostri progetti aziendali e collaborare a produzioni capaci di unire tecnologia, teatro e valore umano.</p>','Come superare gli slogan nell\'innovazione tra IA e teatro per rimettere al centro il valore umano e l\'impatto sociale concreto delle produzioni.',NULL,NULL,NULL,'[\"Intelligenza Artificiale\",\"Teatro Digitale\",\"Innovazione Sociale\",\"Arte e Tecnologia\",\"Impatto Sociale\"]','Oltre la retorica dell\'innovazione: scopri come l\'integrazione tra IA e teatro genera reale valore umano e sociale nelle produzioni artistiche.','','text',NULL,'center','0','https://www.facebook.com/twoemme/posts/pfbid0NnCVPCwqCAY5o4dLsvWmNWngLoxJTkUCoBqxqDx1GnAuHYEZhCTMfAqQNpJZV2TYl','2026-03-03 18:12:12','2026-09-19 11:40:04','73cc62d0eaeea25a09db0c4d557158934c690e3b81d4e2374f1f403b171f6bdc','0','Respinto dal revisore editoriale: Il post è un semplice commento di accordo privo di contesto, sostanza informativa o legame esplicito con la missione su IA e teatro; costituisce puro rumore e non aggiunge valore per i motori di ricerca.','85','done',NULL,'1',NULL,'ia-e-teatro-superare-la-retorica-per-creare-valore-reale','0','0');
INSERT INTO `posts` VALUES ('34','3','facebook','10232330458105600','Tutto molto tristemente chiaro. Dice.. Ma si che sarà mai quest\'antifurto che suona.. tanto suona sempre. E poi ti ritroverai i ladri in casa e tu fuori con le serrature cambiate. Possibile che ancora clo avete capito?','','Sicurezza e prevenzione: non ignorare i segnali d\'allarme','<p>Ignorare i segnali d\'allarme reiterati è uno degli errori più comuni quando si parla di sicurezza domestica e protezione dei propri spazi. Spesso si tende a sottovalutare un allarme che suona frequentemente, declassandolo a mero fastidio o a un falso contatto, senza considerare le conseguenze reali di questa disattenzione.</p><h2>L\'errore di sottovalutare i richiami di attenzione</h2><p>Quando un sistema di sicurezza segnala un\'anomalia, l\'assuefazione al rumore porta a credere che non stia succedendo nulla di grave. La sottovalutazione continua dei rischi espone tuttavia al pericolo concreto di trovarsi di fronte a sorprese sgradite, come l\'intrusione di malintenzionati e la perdita del controllo sui propri beni personali.</p><h2>Proteggere i propri spazi con consapevolezza</h2><p>Prendere sul serio ogni avviso è fondamentale per garantire la propria tranquillità. Una gestione attenta dei sistemi di difesa e una tempestiva risposta ai segnali d\'allarme evitano situazioni paradossali e irreversibili. Reagire prima che sia troppo tardi è l\'unico modo per tutelare efficacemente ciò che ci appartiene.</p>','Sottovalutare i segnali d\'allarme continui espone a rischi gravi. Scopri perché è fondamentale non ignorare i richiami di sicurezza per proteggere i tuoi',NULL,NULL,NULL,'[\"sicurezza\",\"prevenzione\",\"allarme\",\"protezione\",\"consapevolezza\"]','Ignorare i sistemi di allarme può portare a gravi conseguenze. Impara l\'importanza della prevenzione e della risposta tempestiva ai segnali di pericolo.','','text',NULL,'center','0','https://www.facebook.com/twoemme/posts/pfbid02veaXt8wER8jfYKCkxhhJS3Xta1Q3T1FKsWVRc62CEeivsoXM7QryUgsFBtZVXMVYl','2026-02-18 20:04:50','2026-09-19 11:40:04','7cd5576a25a546bbd64de60150b606a342ad682fcd30e48414d57d5be198762b','0','Respinto dal revisore editoriale: Il post è uno sfogo vago e criptico senza contesto specifico, privo di riferimenti ad IA, teatro o progetti artistico-sociali. Costituisce puro rumore social e non apporta valore al sito.','80','done',NULL,'1',NULL,'sicurezza-e-prevenzione-non-ignorare-i-segnali-d-allarme','0','0');
INSERT INTO `posts` VALUES ('35','3','facebook','10232327011579439','Non ci stavo capendo piu\' nulla e ho chiesto attraverso un software che ho sviluppato che più AI si scornassero per capire cosa scegliere la prossimo Referendum del 22 e 23 Marzo. Ecco la risposta.','','Usare l\'IA al Referendum: Un Software tra Intelligenze Artificiali','<p>Di fronte alle decisioni complesse che ci attendono, come il prossimo <strong>Referendum del 22 e 23 Marzo</strong>, comprendere le diverse posizioni può risultare un\'impresa complessa. Per superare la confusione e analizzare al meglio la scelta sul voto, nasce un\'iniziativa che unisce tecnologia, analisi critica e innovazione digitale.</p><h2>Scontro tra Intelligenze Artificiali per capire il voto</h2><p>Per trovare chiarezza e mettere a confronto opinioni differenti, è stato sviluppato un software personalizzato in grado di far interagire e mettere a confronto diretto più sistemi di <strong>Intelligenza Artificiale</strong>. Facendo \'scornare\' tra loro diversi modelli di IA, il programma estrapola argomentazioni e punti di vista contrapposti, offrendo una panoramica neutrale e approfondita sui temi del referendum.</p><h2>Tecnologia al servizio del valore umano</h2><p>L\'obiettivo di questo esperimento digitale non è sostituire la coscienza individuale, ma utilizzare gli strumenti dell\'IA come acceleratori di comprensione e consapevolezza. Mettere l\'innovazione tecnologica al servizio dei cittadini permette di trasformare una scelta politica e sociale in un processo informato e accessibile a tutti.</p><p>Vuoi scoprire come applicare soluzioni di Intelligenza Artificiale e strumenti digitali per raccontare storie, analizzare dati o valorizzare i tuoi progetti? <strong>Contattaci per una consulenza e innova con noi.</strong></p>','Un software basato sull\'Intelligenza Artificiale mette a confronto più modelli per fare chiarezza in vista del Referendum del 22 e 23 Marzo.',NULL,NULL,NULL,'[\"Intelligenza Artificiale\",\"Referendum 22 23 Marzo\",\"Software IA\",\"Innovazione Digitale\",\"Tecnologia e Societa\"]','Scopri il software di IA sviluppato per mettere a confronto diverse intelligenze artificiali e fare chiarezza sul Referendum del 22 e 23 Marzo.','','text',NULL,'center','0','https://www.facebook.com/twoemme/posts/pfbid0oXL2pTvCtyi3Dv8wskeHhJNfYCqzXUiob3LRYdKdXXW5QNq7Jni4AK53DZcfiDrsl','2026-02-18 13:37:53','2026-09-19 11:40:04','366eb5d16b8a42a9b646a3e5d3cdc6a3c646df33ab7eb6c9adb972ae2219d511','0','Approvato dal revisore editoriale: Mostra un utilizzo originale e concreto dell\'IA sviluppata dall\'autore applicata a una decisione di rilevanza civica e sociale, perfettamente in linea con il brand.','85','done',NULL,'1',NULL,'usare-l-ia-al-referendum-un-software-tra-intelligenze-artificiali','1','0');
INSERT INTO `posts` VALUES ('36','3','facebook','10232256134287551','MA perchè io dico Perchè solo all\'ultimo una persona deve capire certe cose. Eppure io per primo ho cercato di portare gli strumenti giusti per non farsi fregare dalla vita. Forse perchè la parola \"chiesa\" fa tanta distanza? E\' il messaggio, il vettore o dove si propone di ascoltare una parola che chiarirebbe tutto che non va?  A S. Achille ci sono catechesi dal 19 Gennaio  dove la media di chi è venuto sono di 2 persone. E tutti gli altri? Già colmi  della sapienza \"umana\"? O talmente storditi da non farsi nessuna domanda? E\' triste, veramente triste dover arrivare alla fine della vita per capire com\'erano le regole del gioco. La speranza è che per tutti ci sia il tempo di capire e di sfruttare l\'aiuto che viene da Dio sin da ora.','','Catechesi a S. Achille: riflettere sul senso della vita','<p>Spesso ci si interroga sul senso profondo dell\'esistenza e sulle regole che la guidano soltanto quando si giunge alle fasi finali della vita. Per offrire un\'occasione di confronto spirituale e personale, la parrocchia di <strong>S. Achille</strong> ha avviato un ciclo di <strong>catechesi aperte al pubblico a partire dal 19 Gennaio</strong>.</p><h2>L\'importanza dell\'ascolto e della ricerca personale</h2><p>Nonostante la disponibilità di strumenti utili per orientarsi di fronte alle difficoltà quotidiane, l\'affluenza agli incontri registra attualmente una media di appena due partecipanti. Questo dato invita a una riflessione sul rapporto tra le persone, il messaggio proposto e la percezione della parola \"chiesa\", che talvolta rischia di creare una distanza ingiustificata.</p><p>La fretta quotidiana e la presunzione di bastare a se stessi attraverso la sola sapienza umana spingono molte persone a trascurare le domande fondamentali. Comprendere le dinamiche della vita prima che sia troppo tardi rappresenta un\'opportunità preziosa per vivere con maggiore consapevolezza.</p><h2>Un invito aperto alla comunità</h2><p>L\'auspicio degli organizzatori è che ciascuno possa trovare il tempo per porsi le giuste domande e accogliere il sostegno spirituale offerto fin da ora. Gli incontri di catechesi presso S. Achille proseguono come uno spazio di ascolto e dialogo aperto a chiunque desideri approfondire questi temi.</p>','Riflessione sul valore delle catechesi avviate il 19 Gennaio a S. Achille per riscoprire il senso della vita e il sostegno spirituale.',NULL,NULL,NULL,'[\"catechesi\",\"S. Achille\",\"riflessione spirituale\",\"eventi 19 gennaio\",\"crescita personale\"]','Scopri il ciclo di catechesi dal 19 Gennaio presso la parrocchia di S. Achille: un\'occasione per riflettere sul senso della vita e la spiritualità.','','text',NULL,'center','0','https://www.facebook.com/twoemme/posts/pfbid05V71kwLyxbDTmeESEMAuBG6B9mUrJPSpH1M6JWEwYqKP1ixWXovZdzZtMCyxqyaBl','2026-02-12 17:05:44','2026-09-19 11:40:04','f9a5acfd143f6961d59e25db9a95d2647cc21e77e99678c3e6477e2e8b66f255','0','Respinto dal revisore editoriale: Il post è uno sfogo personale su temi religiosi e parrocchiali, privo di collegamenti con l\'Intelligenza Artificiale, il teatro o l\'innovazione tecnologica.','82','done',NULL,'1',NULL,'catechesi-a-s-achille-riflettere-sul-senso-della-vita','0','0');
INSERT INTO `posts` VALUES ('37','3','facebook','10232230589248941','Dopo tanto lavoro e studio ci sono riuscito! Finalmente la prima ed unica piattaforma che sonifica le immagini in maniera deterministica. Che vuol dire? Che le immagini vengono \"sigillate\" \"macate\" attraverso la musica. In piu\' le opere generano una musica unica grazie all\'AI che ne orchestra il suono derivante dalla sonificazione. Vai su www.sonificart.com, vai nella gallery ascolta il suono delle immagini.','','SonificArt: la prima piattaforma per sonificare le immagini','<p>Dopo un lungo percorso di studio e sviluppo nasce <strong>SonificArt</strong>, la prima e unica piattaforma capace di trasformare le immagini in musica in maniera deterministica. Un\'innovazione che unisce arte visiva e tecnologia per creare una nuova forma di fruizione e tutela delle opere d\'arte.</p><h2>Come funziona la sonificazione deterministica</h2><p>La sonificazione deterministica consente di \"sigillare\" e \"marcare\" le immagini attraverso il suono. Ogni opera visiva genera una traccia musicale unica: l\'<strong>Intelligenza Artificiale</strong> interviene per orchestrare il suono derivante dalla sonificazione, trasformando i dati visivi in una vera e propria composizione sonora originale e non replicabile.</p><h2>Ascolta il suono dell\'arte</h2><p>Questa tecnologia apre nuove prospettive per artisti, gallerie e appassionati, creando un legame indissolubile tra l\'immagine e la sua identità acustica. Un approccio innovativo che valorizza la creatività digitale attraverso l\'unione tra arte visiva e musica.</p><p>Per esplorare il progetto, scoprire le opere e ascoltare il suono delle immagini, è possibile visitare la gallery sul sito ufficiale <strong>www.sonificart.com</strong>.</p>','Nasce SonificArt, la prima piattaforma che trasforma le immagini in musica deterministica ed unica grazie all\'intelligenza artificiale. Visita la gallery.',NULL,NULL,NULL,'[\"SonificArt\",\"Intelligenza Artificiale\",\"Sonificazione Immagini\",\"Arte Digitale\",\"Musica e AI\"]','Scopri SonificArt, la prima piattaforma che sonifica le immagini in modo deterministico creando musica unica con l\'Intelligenza Artificiale.','','text',NULL,'center','0','https://www.facebook.com/twoemme/posts/pfbid02XMKfsmEsYFwbXngxoXd1zw8PaL9HqzQLqAZBDRYZK2GZfx73hfYVJ1PSqevxXrRgl','2026-02-10 12:38:00','2026-09-19 11:40:04','edbb8c41b59268ca11e7c3b20ea919bf43a4c5e396a72a8f3e8bbdee6914848c','0','Respinto dal revisore editoriale: Il progetto SonificART e il suo metodo deterministico sono già capillarmente trattati in diversi articoli del sito. Il post social è un annuncio sintetico che costituisce un doppione tematico.','85','done',NULL,'1',NULL,'sonificart-la-prima-piattaforma-per-sonificare-le-immagini','0','0');
INSERT INTO `posts` VALUES ('39','3','instagram','3750606199138933562','Sta per uscire il mio nuovo brano. Presto online.','Il video mostra una postazione di produzione musicale composta da due monitor, una tastiera musicale MIDI, una tastiera per computer retroilluminata e un mouse. Sul monitor di sinistra è visibile un software di produzione musicale con una traccia audio e una tastiera virtuale, mentre sul monitor di destra è aperto un altro programma per l\'editing audio, con varie tracce evidenziate. Sullo schermo appare una scritta in sovrimpressione in lingua italiana: \"Sto finendo di lavorare al mio nuovo brano. Sarà una sorpresa, il giusto mix tra AI e realtà\". In sottofondo si sente una musica pop ritmata ed elettronica.','Musica e Intelligenza Artificiale: in arrivo il nuovo brano','<p>La produzione musicale sta attraversando una fase di profonda trasformazione, dove la tecnologia digitale e la creatività umana si fondono per dare vita a nuove forme espressive. È in arrivo un nuovo brano musicale pensato come un perfetto equilibrio tra <strong>Intelligenza Artificiale e realtà</strong>, unendo sonorità pop ritmate ed elettroniche a una visione artistica innovativa.</p><h2>La sinergia tra software digitali e sensibilità artistica</h2><p>Il processo di creazione del singolo si sviluppa attraverso l\'uso di postazioni avanzate di produzione musicale. L\'impiego combinato di software di editing audio, tastiere virtuali e strumenti MIDI permette di plasmare tracce sonore complesse, dove la precisione degli algoritmi di IA si intreccia con l\'espressività umana. L\'obiettivo è offrire all\'ascoltatore un\'esperienza sonora originale, capace di connettere l\'innovazione tecnologica con la sensibilità emotiva.</p><h2>Un\'anteprima del nuovo progetto musicale</h2><p>Attualmente nelle sue fasi finali di lavorazione, il brano sarà presto disponibile online su tutte le principali piattaforme. Questo progetto rappresenta un passo fondamentale nel percorso di esplorazione delle convergenze tra <strong>tecnologia, arte e valore umano</strong>. Continua a seguirci per rimanere aggiornato sulla data di uscita ufficiale e per scoprire in anteprima il lancio del brano.</p>','In arrivo il nuovo brano pop elettronico che unisce Intelligenza Artificiale e creatività umana. Scopri tutti i dettagli sulla prossima uscita online.',NULL,NULL,NULL,'[\"Intelligenza Artificiale\",\"Musica Elettronica\",\"Produzione Musicale\",\"Innovazione Digitale\",\"Nuovo Singolo\"]','In arrivo il nuovo brano musicale che fonde Intelligenza Artificiale e realtà: una traccia pop elettronica che unisce tecnologia e sensibilità artistica.','https://allsocialtoweb.com/public/media/instagram_3750606199138933562.mp4','video',NULL,'center','0','https://www.instagram.com/p/DQM1HdwDds6/','2025-10-24 19:32:06','2026-09-19 15:56:26','d72049c0690755e70ea2b494f58a716a00bd1b442113141e79839e5ce4b5d4e6','0','Respinto dal revisore editoriale: Si tratta di un teaser promozionale molto breve (\'thin content\'). Privo di approfondimento o del brano completo, per il sito web risulterebbe mero rumore privo di valore SEO.','85','done',NULL,'1',NULL,'musica-e-intelligenza-artificiale-in-arrivo-il-nuovo-brano','1','0');
INSERT INTO `posts` VALUES ('45','3','instagram','3548895194900523152','#bellecapocce','Buongiorno a tutti. Questo è il primo video che metto in questo nuovo canale che si chiama \"Belle capocce\". Eh non andava di fare il classico canale autoreferenziale nel quale ognuno dice i cavoli suoi, volevo fare un canale che in qualche modo parlasse di noi. Ma di cosa? Delle belle capocce, in realtà. In dialetto romanesco \"belle capocce\" vuol dire belle teste, belle menti. E non è la... non è una comunità di tutti scienziati che stanno inventando chissà cosa. È una comunità per ognuno di noi perché io credo fermamente che indipendentemente dal tuo livello di cultura, di preparazione o di aspirazione che hai nella vita, c\'hai nella testa un potenziale meraviglioso, meraviglioso che in qualche modo è staccato proprio dal corpo, cioè potresti potenzialmente esserci un corpo bellissimo e una testa non bella e viceversa. Però io voglio partire da un presupposto, che comunque ognuno di noi c\'ha una bella capoccia da dover sfruttare e da dover utilizzare. Se mi seguite in questo canale, io che mi occupo anche di intelligenza artificiale, iniziamo a fare un viaggio meraviglioso assieme per distinguere l\'intelligenza umana da quella artificiale e anche iniziare a ad affrontare quelle che sono le sfide di questo tempo. Seguitemi. Buona domenica.','Differenza tra Intelligenza Umana e Artificiale: Belle Capocce','<p>Nasce il progetto <strong>Belle capocce</strong>, uno spazio editoriale ideato per esplorare il potenziale della mente umana e il suo rapporto con l\'evoluzione tecnologica. L\'espressione romanesca \"belle capocce\", che significa letteralmente \"belle teste\" o \"belle menti\", dà il nome a una community aperta a chiunque voglia valorizzare le proprie capacità intellettive, indipendentemente dal livello di cultura o di preparazione di partenza.</p><h2>Valorizzare il potenziale umano nell\'era dell\'IA</h2><p>Ogni persona possiede nella propria testa un potenziale straordinario da scoprire e sfruttare. Il canale si propone di andare oltre i classici contenuti autoreferenziali per mettere al centro le persone, creando un punto d\'incontro inclusivo dove la crescita personale diventa un percorso condiviso.</p><h2>Un viaggio tra mente umana e tecnologia</h2><p>Attraverso questo percorso, chi si occupa di <strong>intelligenza artificiale</strong> guiderà la community in un viaggio orientato a distinguere l\'intelligenza umana da quella artificiale. L\'obiettivo principale è imparare a comprendere i punti di forza della mente umana e ad affrontare con consapevolezza le grandi sfide del nostro tempo.</p><p>Se vuoi esplorare le opportunità dell\'era digitale e valorizzare la tua creatività, unisciti alla community di Belle Capocce e inizia a far parte di questo cambiamento.</p>','Scopri il progetto Belle Capocce: un viaggio per valorizzare il potenziale della mente umana e comprendere la differenza con l\'intelligenza artificiale.',NULL,NULL,NULL,'[\"intelligenza artificiale\",\"intelligenza umana\",\"belle capocce\",\"innovazione\",\"crescita personale\"]','Scopri Belle Capocce: il progetto che esplora il potenziale della mente umana e affronta le sfide dell\'intelligenza artificiale. Unisciti alla community.','https://allsocialtoweb.com/public/media/instagram_3548895194900523152.mp4','video',NULL,'center','0','https://www.instagram.com/p/DFANWB9IuiQ/','2025-01-19 11:09:40','2026-09-20 19:56:51','b86453c9442f6b0b4d29a9fdde2ffa57e30cd87778c8212652cebba8e3107177','0','Approvato dal revisore editoriale: Il contenuto introduce la nuova rubrica \'Belle capocce\' incentrata sulla valorizzazione dell\'intelligenza umana a confronto con quella artificiale, perfettamente in linea con la missione di connettere IA e valore umano.','85','done',NULL,'1',NULL,'differenza-tra-intelligenza-umana-e-artificiale-belle-capocce','1','0');
INSERT INTO `posts` VALUES ('48','3','instagram','3616324283491702646','IL PORBLEMA DI QUESTO MOMENTO NON SONO LE RIPOSTE MA CHE MANCANO LE DOMANDE. \nSIAMO TUTTI ANIMALI D\'ALLEVAMENTO E ALLA FINE CI STA BENE. MA A CHE PREZZO? DI ESSERE VENDUTI COME CARNE DA MACELLO. A me non va di vivere una vita cosi. E magari (se ci arrivi) vecchio e aspettando ogni giorno di morire. Io voglio vivermela QUI ORA ma per SEMPRE! - VIENI DAL 19 GENNAIO 2026 alle catechesi per adulti e ragazzi. In Via Gaspara Stampa 64 00137 Roma - PArrocchia S. Achille!','Ecco la trascrizione integrale e verbatim di tutto il parlato presente nel video:\n\nLa vita alla fine si affronta in due modi: subendola o vivendola davvero. E in fondo, anche se con strade diverse, cerchiamo tutti la stessa cosa: farcela in qualche modo. \n\nAllora facciamo un patto: se tutto ti va come avevi previsto, non venire. \n\nSe ogni pezzo è al posto, non venire. \n\nSe hai capito come evitare la sofferenza, non venire. \n\nSe non ti manca nulla e va tutto bene, non venire. \n\nSe sulla porta di casa tua c\'è scritto \"non disturbarmi\", non venire. \n\nSe ti senti amato da tutti, sempre e comunque, non venire. \n\nSe non hai paura della morte, non venire. \n\nSe la tua famiglia è quella del Mulino Bianco, non venire. \n\nMa se anche solo una di queste cose ti scricchiola dentro, ti senti in crisi e non riesci a capire da dove ricominciare, pensaci: non è la fine, ma soltanto un nuovo inizio. \n\nPerché tu non sei nato per sopravvivere come una pianta o un animale. Tu sei un essere speciale, creato per vivere, per essere felice. Come fare? Vieni, siediti e per una volta ascolta qualcuno che ti conosce bene, vuole parlarti. \n\nVieni. Vieni.','Catechesi per adulti e giovani a Roma dal 19 gennaio 2026','<p>La vita può essere subita passivamente oppure vissuta con pienezza. Spesso ci si accontenta di sopravvivere, rinunciando a porsi le domande fondamentali sull\'esistenza, sul senso della sofferenza e sulla ricerca di una felicità autentica e duratura.</p><h2>Un percorso per chi affronta momenti di crisi</h2><p>Dal <strong>19 gennaio 2026</strong> prendono il via gli incontri di catechesi dedicati ad adulti e ragazzi a Roma. L\'iniziativa si rivolge a chiunque stia attraversando un momento di difficoltà, incertezza o ricerca personale e desideri trovare un nuovo inizio oltre le apparenze di una vita superficiale.</p><h2>Dove e come partecipare agli incontri</h2><p>Gli appuntamenti si terranno presso la <strong>Parrocchia S. Achille</strong>, situata in Via Gaspara Stampa 64 (00137 Roma). Il percorso invita a fermarsi per ascoltare, confrontarsi e riscoprire il valore profondo dell\'esistenza.</p><ul><li><strong>Data d\'inizio:</strong> 19 Gennaio 2026</li><li><strong>Luogo:</strong> Parrocchia S. Achille, Via Gaspara Stampa 64, Roma</li><li><strong>Destinatari:</strong> Adulti e ragazzi</li></ul>','Percorso di catechesi per adulti e ragazzi dal 19 gennaio 2026 alla Parrocchia S. Achille a Roma. Un\'opportunità di riflessione e rinascita personale.',NULL,NULL,NULL,'[\"Catechesi Roma\",\"Parrocchia Sant Achille\",\"Eventi Roma 2026\",\"Crescita personale\",\"Incontri per adulti\"]','Partecipa alle catechesi per adulti e ragazzi dal 19 gennaio 2026 presso la Parrocchia S. Achille a Roma. Un percorso di riflessione e riscatto.','https://allsocialtoweb.com/public/media/instagram_3616324283491702646.mp4','video',NULL,'center','0','https://www.instagram.com/p/DIvw8aWJFd2/','2025-04-22 12:58:53','2026-09-20 19:57:05','14232df4c11281029737fdb6ad6cef8a370b6553900de2425238adc31863bd7d','0','Respinto dal revisore editoriale: Il contenuto è un invito locale a incontri di catechesi parrocchiale; pur toccando la sensibilità umana ed esistenziale, manca del tutto il legame con l\'Intelligenza Artificiale, il teatro o l\'innovazione digitale.','88','done',NULL,'1',NULL,'catechesi-per-adulti-e-giovani-a-roma-dal-19-gennaio-2026','0','0');
INSERT INTO `posts` VALUES ('50','3','instagram','3751338022466570331','','Il video è un videoclip musicale della canzone \"Sulla Fune Della Vita\" di Marco Mirra, girato in uno stile visivo che alterna immagini in bianco e nero a immagini a colori e si sviluppa attraverso una sequenza di scene suggestive legate al tema del circo, dell\'equilibrio e del volo, con la presenza di vari elementi visivi ed emblematici.\n\nIl video inizia in bianco e nero con un\'inquadratura dall\'alto di un circo, mostrando il tendone principale e le varie carovane circostanti. Nel mentre appare la scritta \"MARCO MIRRA\" in sovrimpressione. \n\nSuccessivamente, la scena cambia per mostrare un uomo con un gilet tattico che si prepara indossando dei guanti senza dita, introducendo un elemento di preparazione e tensione. \n\nSubito dopo, la scena passa a colori e si sposta su una giostra luminosa di un parco divertimenti di notte, illuminata da luci al neon colorate che creano un\'atmosfera vivace e malinconica allo stesso tempo. La giostra è in movimento, con riflessi di luce che si diffondono nell\'ambiente circostante.\n\nLe scene successive mostrano una ballerina in ombra che esegue una danza aggraziata, la sua figura stilizzata contro una luce brillante che la illumina da dietro. Questo aggiunge una dimensione di grazia, movimento ed eleganza, in contrasto con le immagini precedenti. \n\nVerso la fine del video, l\'uomo con il gilet tattico ricompare, mentre applica della magnesite sulle mani, un gesto tipico degli atleti che si preparano a un\'impresa fisica impegnativa. Subito dopo, viene mostrato mentre si esercita con degli anelli da ginnastica, con la figura della ballerina sovrapposta in una dissolvenza incrociata, creando un legame visivo e simbolico tra la forza fisica e la grazia artistica.','Sulla Fune Della Vita: il videoclip di Marco Mirra','<p>Il videoclip ufficiale del brano <strong>\"Sulla Fune Della Vita\"</strong> di Marco Mirra si presenta come un\'opera visiva incentrata sul tema dell\'equilibrio, della forza e del volo drammatico. Attraverso una narrazione per immagini che alterna sapientemente il bianco e nero con l\'uso del colore, il filmato offre una riflessione sulla tensione quotidiana e la grazia artistica.</p><h2>L\'estetica visiva tra circo e preparazione atletica</h2><p>Le prime sequenze, mostrate in un rigoroso bianco e nero, si aprono con un\'inquadratura dall\'alto che riprende il tendone di un circo e le carovane circostanti. La narrazione introduce poi la figura di un uomo che indossa un gilet tattico e guanti senza dita, un elemento che trasmette un forte senso di preparazione fisica e tensione imminente.</p><p>La transizione al colore sposta il focus su una giostra luminosa di notte, creando un contrasto tra l\'atmosfera vivace dei neon e un fondo di malinconia. Successivamente, la comparsa di una ballerina in ombra dona al video un\'eleganza fluida e stilizzata.</p><h2>Forza e grazia: il legame simbolico</h2><p>Nella fase finale, il legame tra sforzo fisico ed espressione artistica si fa ancora più evidente. L\'atleta applica la magnesite sulle mani prima di allenarsi agli anelli da ginnastica. La dissolvenza incrociata tra la sua figura e i movimenti della ballerina crea un parallelismo visivo cruciale tra disciplina corporea e sensibilità poetica.</p>','Scopri il videoclip \"Sulla Fune Della Vita\" di Marco Mirra: un viaggio visivo tra equilibrio, preparazione atletica ed eleganza artistica.',NULL,NULL,NULL,'[\"Marco Mirra\",\"Sulla Fune Della Vita\",\"Videoclip Musicale\",\"Arte e Performance\",\"Teatro e Musica\"]','Analisi del videoclip \'Sulla Fune Della Vita\' di Marco Mirra: un racconto visivo tra il tema del circo, la preparazione atletica e la grazia della danza.','https://allsocialtoweb.com/public/media/instagram_3751338022466570331.mp4','video',NULL,'center','0','https://www.instagram.com/p/DQPbg5ViUhb/','2025-10-25 19:47:07','2026-09-20 19:57:09','e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855','0','Approvato dal revisore editoriale: Il videoclip \'Sulla Fune Della Vita\' riflette appieno la missione dell\'autore nel coniugare espressione artistica, ricerca visivo-teatrale e narrazione delle fragilità/sfide umane, arricchendo il portfolio di produzioni multimediali.','85','done',NULL,'1',NULL,'sulla-fune-della-vita-il-videoclip-di-marco-mirra','1','0');
INSERT INTO `posts` VALUES ('51','3','facebook','1592808145967855','“Perché non mi capisci?”\nA volte non è mancanza d’amore. È che nella relazione parliamo linguaggi diversi, esprimiamo bisogni ed emozioni in modi differenti e ci aspettiamo che l’altro comprenda ciò che non riusciamo a dire.\n\n📌Da 14 settembre 2026 a Roma** prende avvio GRUPPO MISTO, un percorso dedicato a donne e uomini che desiderano comprendere meglio i propri schemi relazionali e sperimentare modalità di comunicazione più autentiche ed efficaci.\n\nDurante gli incontri lavoreremo su temi molto concreti della vita di coppia e delle relazioni:\n\n• comunicazione e fraintendimenti\n• bisogni emotivi e desiderio di riconoscimento\n• conflitti, rabbia e riparazione\n• confini, assertività e rispetto\n• vicinanza, distanza e paura dell’abbandono\n• gelosia, fiducia e controllo\n• aspettative e modelli appresi nella famiglia d’origine\n• ruoli che assumiamo nelle relazioni\n• crisi, separazione e trasformazione del legame\n• amore, desiderio e immaginari della coppia\n\nIl percorso alternerà confronto sui vissuti, approfondimenti teorici, simulate e contenuti grafologici, utilizzati come ulteriore chiave di lettura delle modalità relazionali.\n\n👤 Conduce Dr. Maurizio Bottino, psicoterapeuta e formatore\n✍️ Contenuti grafologici: Roberta Cupiccia, grafologa e formatrice\n\n📍 Puntopiù sas – Via Montecassiano 90, Roma**\n🕖 Incontri dalle **19.00 alle 20.30 circa**\n💶 **40 € per ogni singolo incontro**\n\n⏰Il gruppo è a numero chiuso e le iscrizioni seguiranno l’ordine di prenotazione.\n\n📲 **Prenotazioni: 320 662 3470 o al 338 13 934 23 – anche WhatsApp**\n\nUn\'occasione per osservare le relazioni da una prospettiva diversa e acquisire maggiore consapevolezza su ciò che chiediamo, comunichiamo e ripetiamo nei nostri legami. @follower','L\'immagine cattura un momento di intensa condivisione e ascolto all\'interno di una stanza luminosa e dall\'estetica raffinata. Un gruppo eterogeneo di uomini e donne di varie età è disposto in cerchio su delle sedie, una configurazione che elimina le gerarchie e invita all\'apertura, tipica delle sedute di terapia di gruppo, dei workshop di coaching, del team building aziendale o dei gruppi di supporto.\n\nLa scenografia è caratterizzata da toni caldi e neutri: pareti color sabbia, pavimenti in legno lucido che riflettono la luce naturale proveniente dalle ampie finestre a destra, e grandi piante da interno che aggiungono un tocco di natura ed equilibrio. Sullo sfondo si notano tre quadri coordinati con opere d\'arte astratta dalle forme morbide e dai colori della terra (terracotta, ocra, grigio e nero), che contribuiscono a creare un\'atmosfera serena, accogliente e professionale. \n\nI soggetti indossano abiti curati ma informali nei toni del verde, del blu, del panna e del marrone, perfettamente in armonia con la palette cromatica dell\'ambiente. Al centro dell\'attenzione visiva c\'è una donna dai capelli ricci e dalla giacca color ruggine che parla gestendo con le mani, mentre le persone attorno a lei – inclusi un uomo in maglione scuro di fronte e gli altri partecipanti disposti lungo il cerchio – la ascoltano con evidente empatia, concentrazione e rispetto. L\'inquadratura include le spalle di alcuni partecipanti in primo piano, un dettaglio prospettico che fa sentire l\'osservatore come se fosse seduto all\'interno del cerchio stesso.\n\nSull\'immagine non è presente alcun testo scritto né elemento grafico sovrapposto.\n\nDal punto di vista emotivo e commerciale, l\'immagine trasmette un forte senso di sicurezza psicologica, empatia, connessione umana e ascolto attivo. È una rappresentazione visiva potente del concetto di \"spazio sicuro\" in cui le persone possono aprirsi e confrontarsi. Risulta ideale per contesti editoriali o promozionali legati alla salute mentale, al benessere organizzativo, al counseling, alla crescita personale o alla forza della comunità e della collaborazione.','Migliorare la Comunicazione di Coppia: Il Percorso Gruppo Misto','<p>Molto spesso nelle relazioni interpersonali e di coppia si creano incomprensioni legate all\'uso di linguaggi e schemi emotivi differenti. Dal 14 settembre 2026 prende il via a Roma il percorso <strong>GRUPPO MISTO</strong>, un\'iniziativa pensata per uomini e donne che desiderano approfondire i propri modelli comunicativi e sviluppare relazioni più autentiche e consapevoli.</p><h2>Tematiche e Strumenti del Percorso</h2><p>Il percorso affronta gli aspetti fondamentali delle dinamiche relazionali attraverso il confronto diretto, approfondimenti teorici, simulate pratiche e l\'analisi di contenuti grafologici. Durante gli incontri si lavorerà su temi chiave come:</p><ul><li>Comunicazione, fraintendimenti e gestione dei conflitti</li><li>Bisogni emotivi, assertività, rispetto e confini personali</li><li>Gelosia, fiducia, gestione della distanza e paura dell\'abbandono</li><li>Ruoli, modelli appresi nella famiglia d\'origine e trasformazione dei legami</li></ul><p>Gli incontri saranno condotti dal <strong>Dr. Maurizio Bottino</strong>, psicoterapeuta e formatore, con il contributo della grafologa e formatrice <strong>Roberta Cupiccia</strong> per l\'analisi dei contenuti grafologici.</p><h2>Info Pratiche e Prenotazioni</h2><p>Le sedute si terranno a Roma presso <strong>Puntopiù sas</strong> (Via Montecassiano 90), dalle 19.00 alle 20.30 circa. Il costo è di 40 € per singolo incontro. Essendo un gruppo a numero chiuso, l\'accesso avviene in ordine di prenotazione telefonica o via WhatsApp ai numeri 320 662 3470 oppure 338 13 934 23.</p>','Al via a Roma il percorso Gruppo Misto per comprendere gli schemi relazionali e migliorare la comunicazione. Conduce il Dr. Maurizio Bottino.',NULL,NULL,NULL,'[\"relazioni di coppia\",\"comunicazione assertiva\",\"psicologia roma\",\"crescita personale\",\"gruppo misto\"]','Parte a Roma il percorso Gruppo Misto con il Dr. Maurizio Bottino: un\'opportunità per migliorare la comunicazione e comprendere gli schemi di coppia.','https://allsocialtoweb.com/public/media/facebook_1592808145967855.jpg','image',NULL,'center','0','https://www.facebook.com/MBSeminari/posts/pfbid02QWtebnUH5JgaL7UAP7i6bKxH5Qz8fpXo929GvYLTDuRhi8B2EECzWmCNAdJ8Fi6Pl','2026-08-17 10:00:05','2026-09-21 14:25:46','e1c836baef67b59574da0dca3299da5d64793e0c3af160cca1235ba182d69dbf','0','Respinto dal revisore editoriale: Il contenuto riguarda un evento locale di psicoterapia di gruppo e grafologia gestito da terzi, privo di collegamenti con i temi centrali del profilo (IA, teatro e arte digitale).','88','done',NULL,'1',NULL,'migliorare-la-comunicazione-di-coppia-il-percorso-gruppo-misto','0','0');
INSERT INTO `posts` VALUES ('52','3','facebook','1529493888965948','👉Giovedì 4 giugno dalle ore 19.00\nUltimi posti disponibili - @follower\n🟢Per info e prenotazioni 338.13.93.423 whatsapp','L\'immagine presenta una scena intimista e fortemente cinematografica, costruita attorno a una potente metafora visiva. In primo piano, visto di spalle e leggermente di profilo, c\'è un uomo adulto con capelli corti e scuri, che indossa una maglia a maniche lunghe di colore grigio scuro. È posizionato di fronte a uno specchio ovale con un\'elaborata cornice d\'epoca intagliata, appeso a una parete immersa nella penombra. I toni dell\'ambiente sono caldi e desaturati, dominati da sfumature di marrone, grigio e ocra, con una luce morbida e soffusa che crea un\'atmosfera nostalgica, misteriosa e riflessiva.\n\nL\'elemento centrale della composizione risiede nel riflesso dello specchio: anziché mostrare il volto dell\'uomo adulto, la superficie riflettente rivela l\'immagine di un bambino di circa sei o sette anni. Il piccolo, che indossa una maglietta grigia, guarda dritto davanti a sé con un\'espressione seria, matura e velata di malinconia. Sullo sfondo del riflesso si intravedono la stoffa morbida di una tenda e un quadro appeso, dettagli che arricchiscono il contesto domestico e sospeso nel tempo. Nell\'immagine non è presente alcun testo scritto.\n\nDal punto di vista emotivo e concettuale, l\'autore vuole trasmettere un profondo messaggio legato alla memoria, all\'identità e al concetto psicologico del \"bambino interiore\". L\'immagine suggerisce come il passato e l\'infanzia continuino a vivere dentro l\'adulto, riaffiorando nei momenti di solitudine e introspezione. Può evocare un senso di nostalgia per il tempo trascorso, il desiderio di riconnettersi con la propria innocenza o la necessità di confrontarsi con i ricordi e le emozioni dell\'infanzia. La composizione si presta perfettamente a fare da sfondo a temi legati alla crescita personale, alla psicologia, alla ricerca di sé o all\'elaborazione del proprio vissuto.','Riconnettersi al Bambino Interiore: Evento del 4 Giugno','<p>Il confronto con la propria identità e la memoria del passato è al centro dell\'evento in programma per <strong>giovedì 4 giugno dalle ore 19.00</strong>. Attraverso una potente metafora visiva ed espressiva, l\'incontro invita i partecipanti a riflettere sul concetto psicologico del \"bambino interiore\" e su come l\'infanzia continui a vivere nella vita adulta.</p><h2>Un viaggio tra memoria, identità e introspezione</h2><p>L\'evento propone un percorso di ricerca personale volto a esplorare come i ricordi e le emozioni dell\'infanzia riaffiorino nei momenti di solitudine. Guardarsi allo specchio e ritrovare la propria innocenza rappresenta un passaggio fondamentale per la crescita personale e l\'elaborazione del proprio vissuto emotivo, unendo sensibilità sociale e narrazione visiva.</p><h2>Info e prenotazioni</h2><p>L\'appuntamento si terrà giovedì 4 giugno a partire dalle 19.00. I posti disponibili sono limitati. Per ricevere maggiori informazioni ed effettuare la prenotazione è possibile contattare l\'organizzazione tramite <strong>WhatsApp al numero 338.13.93.423</strong>.</p>','Evento dedicato all\'introspezione e al bambino interiore: giovedì 4 giugno dalle ore 19.00. Ultimi posti disponibili, prenotazioni via WhatsApp.',NULL,NULL,NULL,'[\"evento\",\"crescita personale\",\"bambino interiore\",\"introspezione\",\"psicologia\"]','Partecipa all\'evento del 4 giugno sulle dinamiche del bambino interiore e della memoria. Ultimi posti disponibili: prenota subito via WhatsApp.','https://allsocialtoweb.com/public/media/facebook_1529493888965948.jpg','image',NULL,'center','0','https://www.facebook.com/MBSeminari/posts/pfbid03sqfiL5eoucqwpbWEveoUnthiBswBFf3LuBPSoJByuJcdU5gcCAR7qA52CaE4yZRl','2026-06-03 21:12:48','2026-09-21 14:25:48','18e1817e610ea8bed546332f57b43ae8008ad84ef0bb88ab8525bfcd74e1c017','0','Respinto dal revisore editoriale: L\'immagine è evocativa, ma il testo è una semplice comunicazione logistica e promozionale priva di contesto sull\'evento, risultando di scarso valore editoriale e poco utile per Google.','85','done',NULL,'1',NULL,'riconnettersi-al-bambino-interiore-evento-del-4-giugno','0','0');
INSERT INTO `posts` VALUES ('53','3','facebook','1480549223860415','📌Ricomincio da capo… o ricomincio da me?\n\nQuante volte ci ritroviamo a vivere le stesse dinamiche, le stesse reazioni, gli stessi finali?\n\nA volte cambiano le persone, i contesti, i dettagli… ma qualcosa dentro sembra riportarci sempre allo stesso punto.\nQuesto seminario nasce proprio da qui: dalla possibilità di fermarsi, osservare i propri schemi ricorrenti e iniziare a guardarsi in modo diverso. Attraverso alcune sequenze ispirate al film \"Ricomincio da capo\" e momenti di lavoro esperienziale, sarà possibile riflettere su automatismi emotivi, schemi relazionali e nuove possibilità di risposta.\n\nUn incontro pensato per chi sente di voler uscire da vecchi loop interiori e ritrovare maggiore consapevolezza e libertà personale.\n\nData: 16 aprile 2026\nOrario: 19:00 – 23:00\nSede: Via Montecassiano 90, Roma\nCosto: 40 € | 70 € in coppia\nPrenotazione: WhatsApp al  320 662 3470\nPosti limitati: l’ammissione segue l’ordine di iscrizione. @follower\n\nInfo e registrazione: tramite la pagina evento su PsyEventi.','L\'immagine presenta una scena fortemente suggestiva e dal carattere surrealista, dominata da un\'atmosfera introspettiva e malinconica ma aperta alla speranza. Al centro della composizione figura un uomo visto di spalle, vestito con un cappotto scuro, che cammina da solo lungo un viale innevato e bagnato, le cui pozzanghere riflettono la luce. La strada è incorniciata su entrambi i lati da un\'imponente e surreale fila di giganteschi orologi da sveglia d\'epoca in stile retrò. Lo sfondo della prospettiva converge verso un orizzonte luminoso e dorato, da cui emana la luce calda di un tramonto o di un\'alba, creando un forte contrasto con i toni freddi, grigio-bluastri e innevati del primo piano.\n\nNella parte superiore dell\'immagine è riportata una frase sovrimpressa in testo scuro, perfettamente centrata, che recita testualmente: **«Ricomincio da capo o... ricomincio da me?»**.\n\nIl messaggio emotivo veicolato dall\'autore ruota attorno al tema del cambiamento personale, del tempo che scorre e della ricerca della propria identità. Gli enormi orologi rappresentano la pressione del tempo, le scadenze della vita o il peso del passato, mentre la neve e il freddo simboleggiano una fase di chiusura o di blocco emotivo. Il dilemma posto dal testo mette a confronto due approcci alla vita: il \"ricominciare da capo\", ossia il semplice ripetere da zero un percorso magari guidato dalle aspettative altrui o dalle solite routine, e il \"ricominciare da me\", che implica invece una presa di coscienza interiore, mettendo i propri bisogni e il proprio valore al centro della ripartenza. La figura che cammina verso la luce calda all\'orizzonte simboleggia proprio questa transizione verso la speranza, la consapevolezza e la rinascita personale, rendendo la visuale perfetta come contenuto motivazionale, di crescita personale o per articoli legati alla psicologia e al benessere emotivo.','Seminario Esperienziale: Ricomincio da Capo o da Me?','<p>Quante volte ci ritroviamo a vivere le stesse dinamiche, gli stessi automatismi emotivi e i medesimi schemi relazionali? Spesso cambiano i contesti, ma una spinta interiore ci riporta sempre al punto di partenza. Per uscire da questi loop e ritrovare reale consapevolezza, nasce il seminario esperienziale <strong>«Ricomincio da capo… o ricomincio da me?»</strong>.</p><h2>Un percorso tra cinema e lavoro esperienziale</h2><p>Prendendo ispirazione dalle sequenze del celebre film <em>Ricomincio da capo</em>, l\'incontro offre uno spazio di riflessione e trasformazione. Attraverso momenti di lavoro pratico e guidato, i partecipanti potranno osservare le proprie reazioni e scoprire nuove possibilità di risposta, muovendosi verso una maggiore libertà personale.</p><h2>Informazioni e modalità di partecipazione</h2><p>L\'evento si terrà a Roma ed è aperto a chiunque desideri intraprendere un percorso di crescita e rinascita interiore.</p><ul><li><strong>Data e orario:</strong> 16 aprile 2026, dalle 19:00 alle 23:00</li><li><strong>Sede:</strong> Via Montecassiano 90, Roma</li><li><strong>Costo:</strong> 40 € singolo | 70 € in coppia</li><li><strong>Iscrizioni:</strong> Prenotazione via WhatsApp al 320 662 3470 o tramite la pagina dell\'evento su PsyEventi.</li></ul><p>I posti sono limitati e l\'ammissione seguirà l\'ordine di iscrizione. Un\'occasione unica per fermarsi e rimettere se stessi al centro.</p>','Partecipa al seminario esperienziale il 16 aprile 2026 a Roma. Un percorso tra cinema e lavoro interiore per superare gli schemi ricorsivi.',NULL,NULL,NULL,'[\"seminario esperienziale\",\"crescita personale\",\"psicologia roma\",\"ricomincio da me\",\"eventi roma\"]','Scopri il seminario esperienziale il 16 aprile 2026 a Roma. Supera gli automatismi emotivi e impara a ricominciare da te. Posti limitati.','https://allsocialtoweb.com/public/media/facebook_1480549223860415.jpg','image',NULL,'center','0','https://www.facebook.com/MBSeminari/posts/pfbid02iiQXyLLwvw4iCrVNxHaVvemYTi9sLphr2Adw9ALN47FwZHQKZ3sB3BEWoriEGvcRl','2026-04-07 10:50:08','2026-09-21 14:25:50','4ee4b6bdad46a05933ea16aa888155c5d65cc785ec5959f1ecaad4fe5c07ff7b','0','Respinto dal revisore editoriale: Il contenuto è una locandina promozionale per un seminario locale di crescita personale a pagamento, privo di connessione diretta con l\'IA, il teatro tecnologico o le innovazioni digitali tipiche del profilo.','85','done',NULL,'1',NULL,'seminario-esperienziale-ricomincio-da-capo-o-da-me','0','0');
INSERT INTO `posts` VALUES ('54','3','facebook','1404041348177870','Abramo, Mosè, Davide, Giobbe… sembrano storie “lontane”?\nIn realtà parlano di noi: scelte difficili, dubbi, colpa, ferite, solitudine… e di come attraversarle con più consapevolezza. \nPsy Eventi\n\n📌 Seminario aperto a tutti (online)\nUn percorso esperienziale (non teologico) per rileggere i personaggi biblici come “specchi” interiori e farne strumenti di crescita personale. \n\n🆓 Incontro di presentazione gratuito ONLINE su Zoom: 8 gennaio 2026 – ore 15:00 \n\n👥 Posti limitati: prenotazione obbligatoria \n\n✨ Puoi partecipare anche ai singoli incontri, ma il percorso completo ti dà una visione più coerente e strutturata. \n\n👉 Info e iscrizione dalla pagina dell’evento \n\n📲 Oppure scrivi su WhatsApp al 320 662 3470 per essere ricontattato. @follower','L\'immagine si presenta come la locandina promozionale di un evento formativo, caratterizzata da una struttura grafica divisa verticalmente in due sezioni principali che fondono arte classica e design digitale. \n\nA sinistra spicca il dettaglio di un dipinto a olio dal forte impatto drammatico, raffigurante la celebre scena biblica della lotta di Giacobbe con l\'angelo. L\'opera è dominata da un marcato chiaroscuro di gusto classico e barocco: lo sfondo scuro e i toni caldi della terra concentrano la luce sulle figure protagoniste, in particolare sulle ampie ali bianche e sul drappeggio luminoso dell\'angelo. Lo scontro fisico tra le due figure genera un\'atmosfera carica di tensione, sforzo, ma anche di trascendenza e trasformazione interiore. \n\nLa sezione destra della grafica utilizza forme geometriche oblique e una palette di colori caldi, sfumando dal giallo dorato al marrone bruciato. Su questa superficie è disposto il testo informativo che, considerando i margini dell\'inquadratura, viene trascritto accuratamente come segue:\n- In alto a sinistra, nel riquadro scuro: **`inari interattivi`** (riconducibile alla dicitura \"Seminari interattivi\");\n- Al centro, nel riquadro dorato: **`L\'esperie`** seguito sotto da **`personagg`** (estrapolabili in \"L\'esperienza...\" e \"personaggi...\");\n- Nella parte inferiore: **`Onlin`** (da intendersi come \"Online\") e **`da gennaio a g`** (indicativo del periodo di svolgimento, verosimilmente \"da gennaio a giugno\").\n\nIl messaggio commerciale ed emotivo dell\'autore punta a catturare l\'attenzione di un pubblico colto e motivato, interessato a temi quali la scrittura creativa, la psicologia, la letteratura o la crescita personale. L\'uso dell\'allegoria della lotta con l\'angelo comunica l\'idea di un percorso denso, profondo e sfidante, in cui l\'esperienza del \"personaggio\" o dell\'individuo passa attraverso un conflitto costruttivo per giungere a una nuova consapevolezza. L\'insieme trasmette autorevolezza culturale, professionalità e il valore di un\'esperienza formativa prolungata e interattiva da fruire comodamente online.','I personaggi biblici come specchi interiori: seminario online','<p>Le figure di Abramo, Mosè, Davide e Giobbe raccontano nodi essenziali dell\'esperienza umana: decisioni complesse, dubbi, colpa, ferite e solitudine. Psy Eventi promuove un <strong>seminario esperienziale online</strong> che rilegge questi personaggi tradizionali come veri e propri specchi interiori, offrendo strumenti pratici per attraversare i momenti di conflitto e raggiungere una maggiore consapevolezza di sé.</p><h2>Un percorso esperienziale di crescita personale</h2><p>Non si tratta di un corso teologico, ma di un itinerario formativo interattivo focalizzato sulla psicologia e la crescita personale. Attraverso il confronto con le grandi narrazioni del passato e i conflitti interiori simboleggiati da figure classiche, i partecipanti possono esplorare le proprie dinamiche emotive ed evolutive.</p><h2>Incontro di presentazione e modalità di partecipazione</h2><p>Il percorso si terrà online da gennaio a giugno, con la possibilità di frequentare anche i singoli appuntamenti, sebbene la fruizione completa garantisca una visione più strutturata.</p><ul><li><strong>Presentazione gratuita:</strong> 8 gennaio 2026 alle ore 15:00 su Zoom.</li><li><strong>Modalità:</strong> Online, con posti limitati e prenotazione obbligatoria.</li><li><strong>Iscrizioni:</strong> Prenotazioni dalla pagina dell\'evento o via WhatsApp al numero 320 662 3470.</li></ul>','Partecipa al seminario esperienziale online sui personaggi biblici come strumenti di crescita personale. Presentazione gratuita l\'8 gennaio 2026.',NULL,NULL,NULL,'[\"crescita personale\",\"seminario online\",\"psicologia\",\"sviluppo personale\",\"Psy Eventi\"]','Scopri il seminario esperienziale online sui personaggi biblici come specchi interiori. Presentazione gratuita l\'8 gennaio 2026 su Zoom. Prenota ora.','https://allsocialtoweb.com/public/media/facebook_1404041348177870.jpg','image',NULL,'center','0','https://www.facebook.com/MBSeminari/posts/pfbid0gxQSU2gWRToA64gXakQ5antBEfMREgnLBSUKu23jv448sEvuDgtwuLNBDnhAA2EPl','2026-01-05 12:09:29','2026-09-21 14:25:52','707f438ac526568364cecc4d24984833fe5d2a2d9c2fc70a2f29f7d01e46c9ac','0','Respinto dal revisore editoriale: Il contenuto è la promozione commerciale di un evento/seminario di psicologia terzi (Psy Eventi) estraneo alle tematiche centrali dell\'IA, del teatro e dell\'arte digitale del profilo, risultando irrilevante e assimilabile a rumore promozionale.','88','done',NULL,'1',NULL,'i-personaggi-biblici-come-specchi-interiori-seminario-online','0','0');
INSERT INTO `posts` VALUES ('55','3','facebook','1301894158392590','✨Il 15 settembre 2025 parte il nuovo gruppo donne. Esperienza nata nel 1995, in cui centinaia di donne hanno avuto la possibilità di incontrarsi dando vita a vari gruppi, ognuno diverso dall’altro – perché diverse le storie ed i vissuti delle partecipanti - ma tutti aventi caratteristiche comuni. \n*(L\'incontro del 15 set assume valore di presentazione ed é gratuito per le nuove partecipanti, se decidono di non partecipare ai successivi incontri) per info scrivere al 320 662 3470 - @follower','L\'immagine presenta un\'estetica calda, accogliente e dal gusto raffinato, pensata per comunicare un profondo senso di unione, condivisione e crescita personale al femminile. Lo sfondo è caratterizzato da una texture delicata su toni beige e panna, arricchita al centro da una sfumatura ad acquerello dalle tonalità rosa polvere e malva che dona morbidezza e intimità alla composizione.\n\nSul lato sinistro risalta l\'elemento grafico principale: quattro profili stilizzati di donne sovrapposti che guardano verso destra. Ogni profilo è distinto da una tonalità della palette terrosa e calda — verde salvia, giallo ocra, arancione e rosa tenue — a simboleggiare la diversità delle sfaccettature femminili, la pluralità delle storie individuali e, al tempo stesso, l\'armonia della collettività e della sorellanza.\n\nNella parte destra della grafica è riportato il testo informativo, ben leggibile ed essenziale:\nIn alto domina l\'intestazione principale a lettere maiuscole con un font graziato chiaro, che recita **\"GRUPPO DONNE\"**. Subito sotto, in un carattere lineare di colore viola scuro, vengono forniti i dettagli logistici dell\'evento: **\"Quindicinale, il lunedì\"**, seguito dall\'orario **\"dalle 19:00 alle 20:30\"** e dalla data di inizio **\"dal 15 settembre 2025\"**. In basso a destra, a suggello dell\'iniziativa, si trova il logo circolare della realtà organizzatrice, **\"MB Seminari\"**, incorniciato da un bordo dai riflessi ramati.\n\nIl messaggio emotivo e commerciale dell\'autore mira a invitare le donne a prendersi uno spazio dedicato a se stesse, creando un punto di incontro sicuro, empatico e privo di giudizio. La scelta dei colori caldi, unita al ritmo quindicinale in orario preserale, suggerisce l\'idea di un percorso continuo di riflessione e ricarica emotiva a fine giornata, promuovendo il valore del confronto reciproco e del supporto comunitario promosso da MB Seminari.','Nuovo Gruppo Donne 2025: Incontro di Presentazione Gratuito','<p>Dal 15 settembre 2025 prende il via il nuovo <strong>Gruppo Donne</strong> organizzato da MB Seminari. Si tratta di un\'esperienza e un percorso di confronto nato nel 1995, che nel corso degli anni ha permesso a centinaia di donne di incontrarsi, condividere storie e creare spazi di crescita personale e supporto reciproco.</p><h2>Come funziona il percorso e orari</h2><p>Gli incontri si terranno a cadenza <strong>quindicinale, il lunedì dalle 19:00 alle 20:30</strong>. Ogni gruppo formato negli anni ha saputo sviluppare una propria identità unica grazie alle differenti esperienze delle partecipanti, mantenendo sempre al centro il valore dell\'ascolto e della condivisione in un ambiente sicuro e stimolante.</p><h2>Primo incontro gratuito e iscrizioni</h2><p>L\'appuntamento del <strong>15 settembre 2025</strong> avrà il valore di incontro di presentazione. Per le nuove partecipanti la prima serata è gratuita, qualora decidano di non proseguire con i successivi incontri del percorso.</p><p>Per informazioni ed iscrizioni è possibile contattare direttamente la segreteria organizzativa al numero di telefono <strong>320 662 3470</strong>.</p>','Al via dal 15 settembre 2025 il nuovo Gruppo Donne di MB Seminari. Incontri quindicinali il lunedì. Primo appuntamento di presentazione gratuito.',NULL,NULL,NULL,'[\"Gruppo Donne\",\"MB Seminari\",\"Crescita Personale\",\"Incontri Donne\",\"Condivisione\"]','Scopri il nuovo Gruppo Donne di MB Seminari dal 15 settembre 2025. Incontri il lunedì dalle 19:00 alle 20:30. Primo incontro di presentazione gratuito.','https://allsocialtoweb.com/public/media/facebook_1301894158392590.jpg','image',NULL,'center','0','https://www.facebook.com/MBSeminari/posts/pfbid0zihBHEVSVzZuyATZs8CuGZCStAU6qNDDQjpMeCjWNQaprdUcKErP4yfhVwXzjtY6l','2025-09-03 18:27:32','2026-09-21 14:25:54','8c87420a97d3861737f6d324c64b9667f22bf6d532ff771e71484b1afd3fc452','0','Respinto dal revisore editoriale: Il contenuto è un annuncio promozionale di terzi (MB Seminari) per un gruppo di incontro femminile, del tutto privo di riferimenti all\'Intelligenza Artificiale, al teatro o alla produzione artistica dell\'autore.','85','done',NULL,'1',NULL,'nuovo-gruppo-donne-2025-incontro-di-presentazione-gratuito','0','0');
INSERT INTO `posts` VALUES ('56','3','facebook','1260619085853431','🌸 Gruppo Donne – Spazio di ascolto e confronto in partenza a settembre @follower\n\n📌A chi è rivolto:\nA donne adulte di ogni età, interessate a un percorso di consapevolezza e crescita personale, anche senza esperienze precedenti in gruppo.\n\n🧠Temi trattati:\nRelazioni affettive\nIdentità femminile\nLavoro, famiglia, corpo, autostima\nCambiamenti e fasi della vita\n\n🎯Obiettivo: Creare uno spazio protetto in cui le donne possano condividere esperienze, emozioni, difficoltà e risorse, confrontandosi in modo autentico e non giudicante.\nRichiedi al 320 662 3470','L\'immagine è una locandina promozionale dall\'estetica elegante, minimale e accogliente, pensata per pubblicizzare un percorso di incontri al femminile. \n\nVisivamente, la composizione si divide tra un\'illustrazione d\'impatto sul lato sinistro e una sezione informativa sulla destra, il tutto adagiato su uno sfondo chiaro dal tono beige-avorio con una leggera texture che ricorda la carta d\'arte o l\'effetto acquerello. Sulla sinistra spiccano quattro profili di donna stilizzati e sovrapposti, orientati verso destra. I colori scelti per i profili – verde salvia/oliva, giallo senape, terracotta e rosa cipria – sono caldi, naturali e perfettamente armonizzati tra loro. L\'effetto di trasparenza e sovrapposizione delle sagome simboleggia l\'unione, la vicinanza e l\'intersezione di storie ed esperienze differenti. Dietro il testo sulla destra, una sfumatura circolare dai toni cipria e tortora crea un punto di luce soffuso che rende l\'atmosfera intima e rassicurante.\n\nDal punto di vista del testo riportato sulla grafica, la trascrizione esatta è la seguente:\n\nIn alto a destra, con un font chiaro e tridimensionale grazie a una delicata ombra posteriore, si legge il titolo principale: **GRUPPO DONNE**.\nSubito sotto, in un carattere scuro e ben leggibile, sono riportati i dettagli organizzativi:\n- **Quindicinale, il lunedì**\n- **dalle 19:00 alle 20:30**\n- **dal 15 settembre 2025**\n\nNell\'angolo in basso a destra è presente il marchio dell\'organizzatore, racchiuso in un cerchio dai riflessi metallici color bronzo/rame, con le iniziali stilizzate **MB** e la dicitura **Seminari** in corsivo.\n\nIl messaggio emotivo e promozionale trasmesso dall\'autore è incentrato sui concetti di ascolto, sorellanza, diversità e cura di sé. L\'illustrazione trasmette l\'idea che ogni donna, con la propria unicità e il proprio vissuto (rappresentati dai diversi colori), possa trovare un luogo di confronto e supporto all\'interno della comunità. L\'orario e la frequenza proposti (il lunedì a fine giornata, a cadenza bisettimanale) comunicano la volontà di offrire uno spazio protetto e costante in cui staccare dalla routine per dedicarsi alla crescita personale. L\'insieme visivo trasmette equilibrio, serietà e profonda empatia, invitando il pubblico target a sentirsi accolto e compreso fin dal primo sguardo.',NULL,NULL,NULL,NULL,NULL,NULL,'[]',NULL,'https://allsocialtoweb.com/public/media/facebook_1260619085853431.jpg','image',NULL,'center','0','https://www.facebook.com/MBSeminari/posts/pfbid02KDgf5PKZ6MZb8Kd73534yBdn9q5qFojjvzpuH599oSuy8mfcZkMdFEATJS3w9BBBl','2025-07-14 15:59:52','2026-09-24 17:42:16','20f007378b25242d82c32774dbd67e6567c29f37d920354de58389d70db55209','0','Armonizzazione da riprovare: Gemini (503): This model is currently experiencing high demand. Spikes in demand are usually temporary. Please try again later.','-1','failed',NULL,'1','Gemini (503): This model is currently experiencing high demand. Spikes in demand are usually temporary. Please try again later.',NULL,'0','0');
INSERT INTO `posts` VALUES ('57','3','facebook','1255899759658697','Giovedì 10 luglio,  info e prenotazioni @ 320 662 3470\n@follower','',NULL,NULL,NULL,NULL,NULL,NULL,'[]',NULL,'','text',NULL,'center','0','https://www.facebook.com/MBSeminari/posts/pfbid02P8d6YXfEF2y8kLu4GRA2qHrJMHudTNW8Lv8G2eZYCdxst9GQbF9n1ubvYA2s3LVel','2025-07-08 18:40:44','2026-09-24 17:42:16','e72f1dea5c72ea50a46014de16fde20ca2a05c41ba430e87cbe6246a92510e20','0','Armonizzazione da riprovare: Gemini (503): This model is currently experiencing high demand. Spikes in demand are usually temporary. Please try again later.','-1','failed',NULL,'1','Gemini (503): This model is currently experiencing high demand. Spikes in demand are usually temporary. Please try again later.',NULL,'0','0');
INSERT INTO `posts` VALUES ('58','3','facebook','1222427529672587','“La crisi di coppia non è un problema da risolvere, ma un passaggio necessario per evolvere”\nOgni crisi, anche quelle di coppia, se, da una parte, appaiono come un momento separativo, dall’altra rappresentano un’opportunità per una possibile crescita che difficilmente sarebbe possibile in assenza della crisi stessa \n\n#mauriziobottino_psy #psicologia #psicoterapeuta #psy #cambiamento #consapevolezza #relazioni #coppia #crisidicoppia #amore #separazioni','L\'immagine ritrae un uomo maturo dall\'aspetto autorevole e rassicurante, posizionato in primo piano al centro dell\'inquadratura. L\'ambiente circostante suggerisce un contesto intimo, professionale e accogliente: sullo sfondo si nota infatti un grande quadro incorniciato che raffigura lo scorcio di un borgo antico dai toni caldi dell\'ocra, del terracotta e del marrone. L\'uomo indossa una camicia a righe verticali sottili nei toni del grigio-verde chiaro e beige, con un piccolo pin/distintivo circolare applicato all\'altezza del petto. La palette cromatica generale è dominata da colori caldi e naturali, mentre la luce morbida crea un\'atmosfera serena, riflessiva e professionale.\n\nL\'immagine è impaginata con elementi grafici sovrapposti tipici dei contenuti divulgativi o promozionali per i social media. In alto a destra è ben visibile il logo circolare del brand, incorniciato da un doppio cerchio arancione, contenente la scritta verde **\"MB Seminari\"**. Nella parte centrale, all\'altezza del busto del protagonista, si trova un riquadro grigio semitrasparente arricchito da dettagli geometrici colorati (un triangolo verde sul lato sinistro e uno giallo nell\'angolo in basso a destra). All\'interno di questo riquadro compare il testo principale in lettere bianche, ben visibile e leggibile: **\"COPPIA: la crisi: un passaggio per evolvere\"**.\n\nDal punto di vista emotivo e commerciale, il messaggio principale mira a de-stigmatizzare i momenti di difficoltà all\'interno delle relazioni affettive. Invece di percepire la crisi di coppia come un evento negativo o la fine di un percorso, l\'autore la reinterpreta come una tappa fondamentale e un\'opportunità di crescita condivisa (\"un passaggio per evolvere\"). L\'immagine dell\'esperto, con il suo sguardo diretto, empatico ed esperto, infonde fiducia e speranza, posizionando i \"Seminari MB\" come una risorsa guida preziosa e autorevole per chiunque desideri affrontare e superare le sfide di coppia trasformandole in un\'occasione di evoluzione personale e relazionale.','Crisi di Coppia: Perché è un Passaggio per Evolvere','<p>Le difficoltà all\'interno di una relazione affettiva vengono spesso percepite come il segnale di un fallimento o come un ostacolo insormontabile. Tuttavia, la crisi di coppia non deve essere considerata semplicemente un problema da risolvere o una fase esclusivamente negativa, bensì un passaggio necessario per evolvere e raggiungere una nuova consapevolezza.</p><h2>Un\'opportunità di crescita personale e relazionale</h2><p>Sebbene i momenti critici possano apparire inizialmente come eventi separativi, essi rappresentano in realtà un\'opportunità di crescita condivisa. Senza l\'affiorare di una crisi, difficilmente si creerebbero le condizioni necessarie per interrogarsi profondamente sul rapporto, superare le incomprensioni e maturare una trasformazione individuale e di coppia.</p><h2>I Seminari MB per guidare il cambiamento</h2><p>Attraverso i percorsi dei <strong>Seminari MB</strong>, la gestione delle dinamiche di coppia viene riletta in una chiave evolutiva. Riconoscere il valore del cambiamento permette di affrontare le sfide relazionali con strumenti adeguati, trasformando i momenti di rottura in occasioni di rinascita e coesione.</p>','La crisi di coppia non è un fallimento ma un passaggio necessario per evolvere. Scopri la visione dei Seminari MB per trasformare le difficoltà in',NULL,NULL,NULL,'[\"crisi di coppia\",\"psicologia di coppia\",\"crescita personale\",\"relazioni\",\"MB Seminari\"]','La crisi di coppia è un passaggio fondamentale per evolvere. Scopri l\'approccio dei Seminari MB per affrontare il cambiamento e rafforzare la relazione.','https://allsocialtoweb.com/public/media/facebook_1222427529672587.jpg','image',NULL,'center','0','https://www.facebook.com/reel/2409196742789420/','2025-05-27 12:23:27','2026-09-24 17:42:17','032068d00f62cabd169ea207fdbc2e765263230ce2b6fe2e53124c0db444a66d','0','Respinto dal revisore editoriale: Il contenuto tratta esclusivamente di psicologia e relazioni di coppia (seminari psicoterapeutici) senza alcun legame con l\'Intelligenza Artificiale, la produzione teatrale o l\'arte digitale, risultando fuori target rispetto alla missione del brand.','88','done',NULL,'1',NULL,'crisi-di-coppia-perche-e-un-passaggio-per-evolvere','0','0');
INSERT INTO `posts` VALUES ('59','3','facebook','1216605276921479','MB\n\n “La famiglia può essere il primo luogo dove si tradisce sé stessi”\nLa “felicità” di molte famiglie felici si poggia sulla negazione delle esigenze di alcuni suoi componenti. E, purtroppo, sono spesso le donne a pagare il costo di questo modo di relazionarsi in cui vengono negati i bisogni e i desideri di alcuni\n\n#mauriziobottino_psy #psicologia #psicoterapeuta #psy #cambiamento #consapevolezza #relazioni #famiglia #tradimento #genitori #figli #desideri','L\'immagine ritrae un uomo dall\'aspetto maturo e dallo sguardo serio, concentrato direttamente verso la fotocamera. Indossa un maglione rosso intenso, sul quale è visibile un piccolo microfono a clip che suggerisce la natura divulgativa o promozionale del contenuto, tipica di un video per i social media. Lo sfondo è caratterizzato da eleganti mensole in legno dai toni caldi, su cui poggiano alcuni oggetti d\'arredo decorativi, come una grande sfera chiara e una scultura in legno. In alto a destra è posizionato un logo circolare con la scritta **\"MB Seminari\"**.\n\nAl centro dell\'immagine risalta una grafica sovrapposta: un riquadro scuro semitrasparente, rifinito ai bordi da due piccoli triangoli colorati (uno verde in alto a sinistra e uno giallo in basso a destra), che riporta in grande la frase testuale: \n\n**«FAMIGLIA: il luogo dove si può tradire se stessi»**\n\nDal punto di vista emotivo e comunicativo, l\'autore utilizza una leva fortemente provocatoria per catturare l\'attenzione dell\'osservatore. Il messaggio sovverte la visione tradizionale della famiglia intesa unicamente come luogo di protezione e conforto, introducendo invece un tema psicologico complesso: la possibilità di annullare la propria autenticità o i propri desideri pur di conformarsi alle aspettative familiari. L\'atmosfera seria e autorevole del soggetto, unita alla forte carica emotiva della frase, ha lo scopo commerciale di suscitare curiosità e spingere l\'utente ad approfondire i contenuti, posizionando il brand \"MB Seminari\" come un punto di riferimento per la crescita personale, la psicologia e la risoluzione dei conflitti relazionali.',NULL,NULL,NULL,NULL,NULL,NULL,'[]',NULL,'https://allsocialtoweb.com/public/media/facebook_1216605276921479.jpg','image',NULL,'center','0','https://www.facebook.com/reel/715903170889882/','2025-05-19 16:14:42','2026-09-24 17:42:17','10b6606a5fedd10ee528f4838633109b51f9529f895c94f24b4251827487334e','0','Armonizzazione da riprovare: Gemini (503): This model is currently experiencing high demand. Spikes in demand are usually temporary. Please try again later.','-1','failed',NULL,'1','Gemini (503): This model is currently experiencing high demand. Spikes in demand are usually temporary. Please try again later.',NULL,'0','0');
INSERT INTO `posts` VALUES ('60','3','facebook','1213509820564358','“Non tutte le relazioni devono durare per avere un senso”\nLa bontà di un cibo non dipende dalla quantità… perché dovrebbe esserlo un rapporto?\nSe il tempo, da una parte, dà spazio alla possibilità di conoscersi… a volte è solo lo spazio in cui si declina una percezione scontata e priva di novità dell’altro.\n\n#mauriziobottino_psy #psicologia #psicoterapeuta #psy #cambiamento #consapevolezza #relazioni #coppia #amicizia #tempo','L\'immagine propone il primo piano di un uomo maturo dall\'aspetto autorevole e rassicurante, posizionato al centro della composizione e rivolto direttamente verso la fotocamera. L\'uomo, con capelli e barba corti di colore grigio e occhi chiari espressivi, indossa un maglione lavorato a maglia di colore grigio-marrone sopra una camicia chiara. Sul petto è ben visibile un piccolo microfono a clip circolare, dettaglio che rivela chiaramente la natura divulgativa o di registrazione di un contenuto video. Lo sfondo è caratterizzato da una parete su cui è appesa una grande cornice contenente una collezione ordinata di tessere artistiche rettangolari in legno o cartone, lavorate con varie texture e incisioni. L\'illuminazione è calda e diffusa, creando un\'atmosfera professionale, intima e accogliente.\n\nNell\'angolo in alto a destra è presente un logo circolare dal bordo arancione con all\'interno la scritta in corsivo verde scuro \"MB Seminari\". Al centro del fotogramma, sovrapposta alla figura dell\'uomo, si trova una grafica a forma di riquadro grigio scuro semitrasparente, impreziosita da due accenti geometrici: un triangolo verde nell\'angolo superiore sinistro e uno giallo in quello inferiore destro. All\'interno del riquadro è riportato con chiarezza il seguente testo in lettere maiuscole e minuscole di colore bianco: \n\n**«RELAZIONI: sono migliori quelle lunghe o brevi?»**\n\nDal punto di vista emotivo e commerciale, l\'immagine è progettata per ingaggiare il pubblico su un tema di forte rilevanza psicologica e personale. Lo sguardo diretto dell\'oratore stabilisce un contatto empatico immediato con lo spettatore, trasmettendo un senso di ascolto e competenza. La domanda posta in evidenza fa leva sulla curiosità e sui dubbi comuni legati alla sfera affettiva, invitando alla riflessione. L\'obiettivo commerciale dell\'autore è quello di promuovere i contenuti formativi o di counseling legati al brand \"MB Seminari\", posizionando il relatore come una figura di riferimento esperta capace di offrire risposte e spunti di riflessione di valore sul tema delle relazioni interpersonali.',NULL,NULL,NULL,NULL,NULL,NULL,'[]',NULL,'https://allsocialtoweb.com/public/media/facebook_1213509820564358.jpg','image',NULL,'center','0','https://www.facebook.com/reel/1414255826266503/','2025-05-15 10:22:46','2026-09-24 17:42:18','ff4a1e9ecca78ad7f1ee3df3c4f2a2522c52c2ef8df6878dbbfedd3c96b7b78d','0','Armonizzazione da riprovare: Gemini (503): This model is currently experiencing high demand. Spikes in demand are usually temporary. Please try again later.','-1','failed',NULL,'1','Gemini (503): This model is currently experiencing high demand. Spikes in demand are usually temporary. Please try again later.',NULL,'0','0');
INSERT INTO `posts` VALUES ('61','3','facebook','1211630920752248','Voler essere un ‘buon genitore’ può essere l’atto più narcisistico che compiamo”\nEssere un buon genitore, a volte, nasce dall’esigenza di essere diversi dai genitori che abbiamo avuto. Ma non si considera che, spesso, l’essere altro da qualcuno “cattivo” non serve, per forza, ad essere migliori… forse serve più a confermare la nostra immagine ideale.\n\n#mauriziobottino_psy #psicologia #psicoterapeuta #psy #cambiamento #consapevolezza #relazioni #genitori #figli #perfezione #narcisismo','L\'immagine in formato verticale ritrae un uomo maturo dallo sguardo sereno e diretto verso l\'obiettivo, capace di instaurare un contatto visivo immediato e umano con chi guarda. Il soggetto indossa un maglione di un rosso vivo e caldo, da cui spunta il colletto di una camicia chiara; sul petto è ben visibile un piccolo microfono a clip, dettaglio che rivela chiaramente la natura divulgativa o di registrazione video del contenuto. \n\nSullo sfondo si intravede un ambiente accogliente e familiare: a sinistra campeggia un quadro con una cornice importante sui toni del marrone e dell\'oro, raffigurante un paesaggio dallo stile mediterraneo con case in pietra e tetti in terracotta, mentre sulla destra si nota una struttura in legno dal sapore rustico. L\'illuminazione è calda e avvolgente, contribuendo a creare un\'atmosfera intima, professionale ma al contempo accessibile e priva di formalismi eccessivi.\n\nIn alto a destra è posizionato un logo circolare con bordo arancione contenente la scritta **\"MB Seminari\"**. Al centro del fotogramma, in evidenza sul petto dell\'uomo, è presente un riquadro grafico semitrasparente grigio scuro, rifinito da un triangolo verde in alto a sinistra e uno giallo in basso a destra. All\'interno di questo box è riportato in modo chiaro il seguente testo:\n\n**«GENITORI:**\n**la perfezione?**\n**... no, grazie!»**\n\nIl messaggio emotivo e promozionale trasmesso dall\'autore punta a scardinare il mito del \"genitore perfetto\", affrontando una tematica di forte impatto psicologico e sociale. L\'obiettivo è alleggerire il senso di colpa e l\'ansia da prestazione che spesso affliggono le famiglie moderne, offrendo una prospettiva più realista, empatica e umana. Dal punto di vista commerciale e informativo, l\'immagine serve da gancio visivo per promuovere un seminario, un corso o un video divulgativo targato \"MB Seminari\", invitando genitori ed educatori a un confronto sereno, costruttivo e privo di giudizi sul complesso mestiere di crescere i figli.',NULL,NULL,NULL,NULL,NULL,NULL,'[]',NULL,'https://allsocialtoweb.com/public/media/facebook_1211630920752248.jpg','image',NULL,'center','0','https://www.facebook.com/reel/1390421528654091/','2025-05-12 16:33:09','2026-09-24 17:42:19','78f8e88d797577b1bd99f8f9690a511e6dd509a0e954cbdb6f3eca0b3e2aa469','0','Armonizzazione da riprovare: Gemini (503): This model is currently experiencing high demand. Spikes in demand are usually temporary. Please try again later.','-1','failed',NULL,'1','Gemini (503): This model is currently experiencing high demand. Spikes in demand are usually temporary. Please try again later.',NULL,'0','0');
INSERT INTO `posts` VALUES ('62','3','facebook','1207167277865279','Tradire, etimologicamente, significa portare qualcosa da un’altra parte. E nella storia delle relazioni, a volte, è solo un inadeguato e doloroso modo per dare una risposta a spinte interne che chiedono risposta a bisogni antichi.\n\n#mauriziobottino_psy #psicologia #psicoterapeuta #psy #cambiamento #consapevolezza #relazioni #coppia #tradimento #amore','L\'immagine ritrae in primo piano un uomo maturo dall\'aspetto rassicurante ed espressivo, con capelli corti e barba brizzolata, che fissa direttamente la fotocamera con un\'espressione seria e riflessiva. Indossa un maglione di lana color tortora/grigio, su cui è applicato un piccolo microfono a spilla lavalier di forma circolare, indice che si tratta del fotogramma di un video o di una registrazione promozionale. Alle sue spalle si intravede uno sfondo domestico ma curato, dominato da una grande cornice su parete chiara al cui interno sono disposte, in modo ordinato, numerose tessere rettangolari in legno o carta decorata dai toni caldi ed metallici. L\'atmosfera generale è intima, professionale e orientata all\'ascolto.\n\nDal punto di vista grafico, in alto a destra è posizionato un logo circolare bordato d\'arancio con la dicitura **\"MB Seminari\"**. Al centro del busto dell\'uomo è sovrapposto un riquadro grafico grigio scuro e semitrasparente, rifinito da un triangolo verde nell\'angolo superiore sinistro e un triangolo giallo in quello inferiore destro. All\'interno di questo box è riportato accuratamente il seguente testo in lettere bianche: **«RAPPORTI: chi tradisce non ama?»**.\n\nIl messaggio emotivo e commerciale veicolato dall\'immagine si gioca su una domanda aperta e altamente provocatoria che tocca una delle dinamiche più complesse e sofferte delle relazioni di coppia: l\'infedeltà. Sollevando il dubbio sul legame diretto tra il tradimento e la mancanza d\'amore, l\'autore punta a scardinare un luogo comune, creando un forte ingaggio emotivo con l\'osservatore. L\'obiettivo commerciale è quello di attrarre un pubblico interessato alla psicologia relazionale e alla crescita personale, promuovendo i contenuti e i percorsi formativi offerti da \"MB Seminari\" e posizionando il relatore come una figura esperta, empatica e priva di giudizio moralistico.',NULL,NULL,NULL,NULL,NULL,NULL,'[]',NULL,'https://allsocialtoweb.com/public/media/facebook_1207167277865279.jpg','image',NULL,'center','0','https://www.facebook.com/reel/1980944082316245/','2025-05-06 12:20:18','2026-09-24 17:42:19','b73e49a16ffe77411b85344aa8d6cc4b2c18e5e8fd6d6ab4c495b24ce70f5dc2','0','Armonizzazione da riprovare: Gemini (503): This model is currently experiencing high demand. Spikes in demand are usually temporary. Please try again later.','-1','failed',NULL,'1','Gemini (503): This model is currently experiencing high demand. Spikes in demand are usually temporary. Please try again later.',NULL,'0','0');
INSERT INTO `posts` VALUES ('63','3','facebook','1189330066315667','🎭 “Ognuno di noi ha tre vite: una privata, una pubblica e una segreta.” – Gabriel Garcia Márquez\n\nCosa accadrebbe se il nostro lato più nascosto venisse improvvisamente alla luce?\n\nIn un noto film, bastava un messaggio sul cellulare per far crollare certezze, relazioni, identità. Proprio come nella vita: ciò che non mostriamo – le fragilità, i desideri, i dolori – può diventare una prigione interiore. Nasconderli ci allontana dagli altri… e da noi stessi.\n\n🔍 Il seminario “Sconosciuti a noi stessi”, condotto dal Dott. Maurizio Bottino, è un invito a guardare con sincerità dentro di noi.\nUn percorso tra immagini cinematografiche, riflessione condivisa e convivialità, per esplorare insieme il valore del “segreto” e la possibilità di un’esistenza più autentica.\n\n📅 giovedì, 24 aprile 2025\n🕖 Ore 19.00 – 23:00\n📍 Via Montecassiano,90\n🎟️ con prenotazione anche tramite WhatsApp \n320 662 3470\n\n💬 Per chi sente il bisogno di riconciliarsi con ciò che è, senza più maschere.\n\n🔗 Info e iscrizioni: @follower\n👉 psyeventi.it/eventi-psicologia/sconosciuti-a-noi-stessi-c6773.html\n\n#Psicologia #Segreti #VitaAutentica #MaurizioBottino #CrescitaPersonale #Psyeventi #Torino #Inconscio #cinemaepsicologia','L\'immagine si presenta come una locandina promozionale moderna ed elegante, caratterizzata da una composizione pulita e un\'atmosfera luminosa e introspettiva. Lo sfondo è dominato dai toni del bianco e del beige chiaro, su cui si snoda sinuosa una pellicola cinematografica da 35 mm in bianco e nero. I dettagli dei fotogrammi e dei perfori del rullino creano un senso di movimento e profondità, evocando immediatamente il mondo del cinema, della memoria e della narrazione visiva. Al centro dell\'immagine trova spazio una fascia orizzontale semitrasparente che ospita gli elementi testuali principali, conferendo un aspetto professionale e ben strutturato.\n\nSulla parte sinistra della fascia centrale è posizionato un logo circolare racchiuso da una doppia linea dai toni ramati o terracotta, al cui interno si legge la scritta calligrafica «MB Seminari» in un elegante colore verde scuro. Il testo principale, perfettamente centrato all\'interno del riquadro, riporta in stampatello maiuscolo la parola «SEMINARIO», seguita dal titolo dell\'incontro, «Sconosciuti a se stessi», e dalla data di svolgimento, il «24 aprile 2025». Sia il titolo che la data sono realizzati in un carattere lineare e pulito, nello stesso colore verde scuro del logo, creando un\'armonia visiva coerente.\n\nL\'intento commerciale della grafica è quello di promuovere un evento formativo o divulgativo, ma il messaggio emotivo va molto più a fondo: l\'associazione tra la pellicola cinematografica e il titolo \"Sconosciuti a se stessi\" suggerisce un viaggio di esplorazione interiore, in cui il cinema o l\'immagine diventano uno specchio dell\'inconscio e della psiche umana. L\'uso di toni soffusi e della luce diffusa trasmette serenità, introspezione e autorevolezza, invitando l\'osservatore a riflettere sulle proprie dimensioni nascoste e a partecipare a un momento di arricchimento personale e culturale.',NULL,NULL,NULL,NULL,NULL,NULL,'[]',NULL,'https://allsocialtoweb.com/public/media/facebook_1189330066315667.jpg','image',NULL,'center','0','https://www.facebook.com/MBSeminari/posts/pfbid032o3VQHsKVXQZZTkQyrAAsN1PtYEDFv9Uu4Pd8uCUtseb64oaNppoWmyy2EezVKhPl','2025-04-13 21:04:11','2026-09-24 17:42:22','061e951255b02f52262d59bff0cf8717f3a162e2e00992c841092bff1d735960','0','Armonizzazione da riprovare: Gemini (503): This model is currently experiencing high demand. Spikes in demand are usually temporary. Please try again later.','-1','failed',NULL,'1','Gemini (503): This model is currently experiencing high demand. Spikes in demand are usually temporary. Please try again later.',NULL,'0','0');
INSERT INTO `posts` VALUES ('64','3','facebook','1184176383497702','Ma ci interessa che le nostre famiglie siano perfette? A patto che lo debbano essere per forza… dovrebbe interessarci che le nostre famiglie siano vere: che le persone parlino di se stesse e si raccontino, reciprocamente, lo stato della loro anima\n\n#mauriziobottino_psy #psicologia #psicoterapeuta #psy #cambiamento #consapevolezza #famiglia #perfezione #verità #amore','L\'immagine mostra un uomo maturo dal volto espressivo e dallo sguardo attento rivolto verso la fotocamera, ritratto a figura mezza busto con le mani delicatamente intrecciate. L\'uomo ha capelli grigi e indossa un maglione scuro a trama lavorata, sotto il quale si intravede il colletto di una camicia chiara; sul petto è visibile un piccolo microfono a spilla, elemento che suggerisce la registrazione di un video o di una conferenza. L\'ambientazione è intima e accogliente, caratterizzata da una parete dai toni neutri del beige su cui è appeso un quadro astratto vivace, dominato da pennellate di arancione, magenta e viola. \n\nIn alto a destra è presente un logo circolare con bordo arancione contenente la scritta **\"MB Seminari\"** in verde scuro. Al centro dell\'immagine spicca un riquadro grafico semitrasparente scuro, impreziosito da dettagli geometrici di colore verde in alto a sinistra e giallo in basso a destra. All\'interno del riquadro è riportata la seguente frase in testo bianco ben leggibile: **\"FAMIGLIA: a chi interessa la perfezione?\"**.\n\nDal punto di vista emotivo e commerciale, l\'immagine vuole trasmettere un messaggio di empatia, rassicurazione e decompressione emotiva. Con questa domanda provocatoria e riflessiva, l\'autore mira a scardinare il mito della \"famiglia perfetta\", invitando le persone a liberarsi dalle pressioni sociali e dai sensi di colpa legati a modelli irrealizzabili. La presenza pacata ed esperta del relatore crea una sensazione di fiducia e ascolto. L\'obiettivo commerciale è attirare l\'attenzione di un pubblico interessato alla crescita personale, alla psicologia e alle dinamiche familiari, invitandolo a seguire i contenuti o i corsi formativi proposti da \"MB Seminari\" per ritrovare una visione più autentica, reale e serena della vita familiare.',NULL,NULL,NULL,NULL,NULL,NULL,'[]',NULL,'https://allsocialtoweb.com/public/media/facebook_1184176383497702.jpg','image',NULL,'center','0','https://www.facebook.com/reel/625530193791913/','2025-04-07 13:24:19','2026-09-24 17:42:22','2dbcefff38cbebae00ce9105e9699e4b4c4b79dc44042dc5e656d7f5448524c6','0','Armonizzazione da riprovare: Gemini (503): This model is currently experiencing high demand. Spikes in demand are usually temporary. Please try again later.','-1','failed',NULL,'1','Gemini (503): This model is currently experiencing high demand. Spikes in demand are usually temporary. Please try again later.',NULL,'0','0');
INSERT INTO `posts` VALUES ('65','3','facebook','1176607057587968','🎯L\'opportunità di partecipare, in qualità di relatore, al convegno ECM su \"La violenza contro gli operatori sanitari: un fenomeno da arginare\" è stata un\' occasione non solo per contribuire alla riflessione sui temi della criticità nella comunicazione medico-paziente, ma anche per conoscere, dalla viva voce dei partecipanti, la preziosità e le difficoltà di un lavoro di cui tutti dovremmo essere grati.\nCredo fortemente che promuovere una comunicazione efficace e consapevole sia fondamentale per migliorare, non solo il benessere dei pazienti, ma anche quello degli operatori sanitari stessi, riducendo così le situazioni di conflitto e potenziale aggressività.\n\n🤗Ringrazio gli organizzatori di OMCeO Chieti ORDINE DEI MEDICI CHIRURGHI E DEGLI ODONTOIATRI DELLA PROVINCIA DI CHIETI per la sensibilità dimostrata nella scelta di questa importante tematica e per la calorosa accoglienza riservatami.','L\'immagine ritrae un momento di incontro pubblico o una conferenza all\'interno di una sala elegante e ben illuminata, caratterizzata da pareti e pavimenti nei toni del beige chiaro, finiture in legno coordinato per la scalinata laterale e uno stemma scultoreo raffigurante un\'aquila su una colonna decorativa. Sulla sinistra si nota la presenza di un pianoforte a coda nero e, alle spalle dei presenti, un grande schermo da proiezione che mostra l\'immagine di una balena immersa nel blu dell\'oceano, affiancato da un tendaggio rosso che delimita l\'area del palco.\n\nAl centro della scena figurano sei persone disposte in linea di fronte al pubblico, impegnate in un momento di confronto istituzionale o divulgativo. Tra di esse spicca un giovane uomo al centro, vestito con un abito scuro, camicia bianca e cravatta rossa, che impugna un microfono ed è colto nell\'atto di parlare alla platea con gesti espressivi. Intorno a lui, cinque interlocutori – una donna con un cappotto a scacchi sulla sinistra e quattro uomini con un abbigliamento che varia dal piumino scuro al completo spezzato con jeans – lo ascoltano con attenzione e concentrazione, mantenendo posture composte e riflessive. L\'atmosfera generale appare seria, professionale e al contempo partecipativa.\n\nPer quanto riguarda gli elementi testuali presenti nello scenario, sullo sfondo, affissi al drappo rosso sopra il tavolo, si intravedono dei volantini promozionali o di sensibilizzazione nei quali si distingue chiaramente il testo in stampatello **\"NO ALLA\"** evidenziato su fondo giallo, seguito da altre righe di testo più piccole legate probabilmente a una campagna sociale o di protesta locale. Inoltre, sul lato sinistro, in prossimità del pianoforte, è visibile un cartellino segnaposto bianco rigido, tipico delle conferenze ufficiali.\n\nIl messaggio emotivo e comunicativo trasmesso dalla foto è fortemente legato ai concetti',NULL,NULL,NULL,NULL,NULL,NULL,'[]',NULL,'https://allsocialtoweb.com/public/media/facebook_1176607057587968.jpg','image',NULL,'center','0','https://www.facebook.com/MBSeminari/posts/pfbid0x2rRCCgYv47BuB6p7RQQwhZkk3Q6ieRxTQAqKYMxkAtsg3QJ6pzqqPv2Wfjx8S7ql','2025-03-29 15:26:51','2026-09-24 17:42:23','079e81f6e47e9c2b773b7202643a295d99e8eaff2694c8091e2597f82636b6ce','0','Armonizzazione da riprovare: Gemini (503): This model is currently experiencing high demand. Spikes in demand are usually temporary. Please try again later.','-1','failed',NULL,'1','Gemini (503): This model is currently experiencing high demand. Spikes in demand are usually temporary. Please try again later.',NULL,'0','0');
INSERT INTO `posts` VALUES ('66','3','facebook','1174091934506147','Il progetto dà un senso alla vita delle persone purché non diventi un padrone a cui, come schiavi, dobbiamo assoggettarci. È il solito problema che emerge quando si scambia il mezzo con il fine\n\n#mauriziobottino_psy #psicologia #psicoterapeuta #psy #cambiamento #consapevolezza #vita #scopo #sensodellavita','L\'immagine propone un primo piano di un uomo maturo dal volto espressivo, con capelli corti e barba grigi. Lo sguardo è rivolto direttamente all\'obiettivo con un\'espressione seria, matura e riflessiva, mentre tiene le braccia incrociate sul petto in una postura che comunica al tempo stesso autorevolezza e ascolto. Indossa un maglione rosso acceso che stacca nettamente sullo sfondo; dal colletto si intravede una camicia chiara e sul petto è presente una piccola spilla circolare. L\'ambiente circostante suggerisce un interno accogliente e professionale, caratterizzato da pareti dai toni caldi del giallo e beige, una mensola di legno scuro e un quadro sfocato dai toni aranciati, illuminati da una luce morbida che crea un\'atmosfera intima e introspettiva.\n\nNella parte centrale della figura è sovrapposta una fascia rettangolare scura e semitrasparente, rifinita ai lati da due dettagli geometrici colorati: un triangolo verde in alto a sinistra e uno giallo in basso a destra. All\'interno della fascia compare la scritta in testo bianco e ben leggibile: **«VITA: come il progetto può dare un senso?»**. In alto a destra è posizionato un logo circolare bordato d\'arancione con la dicitura **«MB Seminari»**, scritta in un font corsivo elegante.\n\nDal punto di vista emotivo e commerciale, l\'immagine è studiata per intercettare chi si trova in un momento di riflessione o ricerca di orientamento personale. L\'espressione del protagonista trasmette empatia ed esperienza, proponendolo come una guida affidabile nel percorso di crescita personale. Il messaggio chiave fa leva su un bisogno profondo dell\'individuo: trovare una direzione e uno scopo nella propria esistenza attraverso la progettualità. L\'intento commerciale è quello di promuovere le attività formative di \"MB Seminari\", catturando l\'attenzione degli utenti sui social media mediante una domanda essenziale e profonda, capace di generare curiosità e spingere all\'approfondimento dei contenuti proposti.',NULL,NULL,NULL,NULL,NULL,NULL,'[]',NULL,'https://allsocialtoweb.com/public/media/facebook_1174091934506147.jpg','image',NULL,'center','0','https://www.facebook.com/reel/1031042338841098/','2025-03-26 20:52:13','2026-09-24 17:42:24','ced6679d34be2c10d901d03e2b8596f36ecf85dae0a08abbb9d76f83c1483884','0','Armonizzazione da riprovare: Gemini (503): This model is currently experiencing high demand. Spikes in demand are usually temporary. Please try again later.','-1','failed',NULL,'1','Gemini (503): This model is currently experiencing high demand. Spikes in demand are usually temporary. Please try again later.',NULL,'0','0');
INSERT INTO `posts` VALUES ('67','3','facebook','1168056885109652','Compromesso: parola sindacale, da tavolo delle trattative, da assemblea azionaria… due che si amano parlano di ascolto, accettazione del bisogno dell’altro, di accoglienza e di decisione comune in cui il “compromesso” si misura nella capacità di amare\n\n#mauriziobottino_psy #psicologia #psicoterapeuta #psy #cambiamento #consapevolezza #coppia  #compromessi  #relazioni #ascoltare #amore','L\'immagine ritrae in primo piano un uomo maturo dallo sguardo intenso e diretto, rivolto verso la telecamera per stabilire una connessione immediata con l\'osservatore. L\'uomo, che presenta capelli e barba grigi e occhi chiari, indossa un maglione di maglia blu scuro abbinato a una camicia. Lo sfondo è un interno domestico o uno studio professionale dai toni caldi e neutri, arricchito da quadri astratti alle pareti e una mensola sulla destra, elemento che conferisce all\'ambiente un\'atmosfera intima, accogliente e al tempo stesso autorevole. In alto a destra è presente un logo circolare con bordo arancione contenente la dicitura **\"MB Seminari\"**. \n\nNella parte centrale della foto si trova una grafica sovimpressa, composta da un riquadro scuro semitrasparente delimitato da due dettagli geometrici colorati (uno verde in alto a sinistra e uno giallo in basso a destra). Il testo trascritto accuratamente dall\'immagine recita:\n\n**COPPIA:**\n**Compromessi?**\n**Una parola \"fastidiosa\"**\n\nDal punto di vista comunicativo ed emotivo, l\'autore utilizza una strategia di *hook* (gancio) basata sulla provocazione e sul capovolgimento di un luogo comune. Il concetto di \"compromesso\", solitamente visto come la chiave fondamentale per far funzionare una relazione affettiva, viene qui messo in discussione e definito una parola \"fastidiosa\". Questo crea immediata curiosità e spinge l\'utente a chiedersi il perché di tale affermazione. L\'intento commerciale e divulgativo è quello di promuovere i contenuti o i corsi di \"MB Seminari\", posizionando il relatore come un esperto di relazioni di coppia capace di offrire una prospettiva profonda, innovativa e non banale sulle dinamiche di vita a due.',NULL,NULL,NULL,NULL,NULL,NULL,'[]',NULL,'https://allsocialtoweb.com/public/media/facebook_1168056885109652.jpg','image',NULL,'center','0','https://www.facebook.com/reel/1704009226911200/','2025-03-19 17:35:52','2026-09-24 17:42:25','76331187560ee0c51162aa6a0b4ff87c303b6832d723e06e6894bdc1d7ab0cac','0','Armonizzazione da riprovare: Gemini (503): This model is currently experiencing high demand. Spikes in demand are usually temporary. Please try again later.','-1','failed',NULL,'1','Gemini (503): This model is currently experiencing high demand. Spikes in demand are usually temporary. Please try again later.',NULL,'0','0');
INSERT INTO `posts` VALUES ('68','3','facebook','1167788911803116','Come desideriamo vivere?\nPercorrendo giorno dopo giorno gli stessi passi o vivendo un’esistenza colorata dalla fantasia e dal sogno?\n🔥Seminario Film Tematico giovedì 3 aprile ore 19.00 \n🎯Programma:\nProiezione del film - Piccolo buffet - Interazione seminariale - Considerazioni finali\n⏳Posti limitati - prenota il tuo posto al 320 662 3470 o dr.mbottino@gmail.com @follower','L\'immagine si presenta come locandina promozionale dall\'estetica elegante, pulita e minimale, dominata visivamente da suggestivi nastro di pellicola cinematografica in miniatura che fluttuano e si curvano sullo sfondo. La palette cromatica si gioca su toni caldi e neutri, sfumando dal bianco luminoso a tonalità beige e marrone scuro celluloide, creando un\'atmosfera intima, culturale e riflessiva. Al centro dell\'immagine, una fascia orizzontale semitrasparente mette in risalto il testo informativo, affiancata sulla destra da un piccolo logo circolare arancione che racchiude la sigla \"MB Seminari\".\n\nIl testo riportato sull\'immagine recita testualmente: \n\"Seminario Tematico\"\n\"Il racconto della nostra storia\"\n\"3 aprile ore 19.00 - Roma\"\n\"proiezione di immagini filmiche “BIG FISH”\"\n\nDal punto di vista comunicativo ed emotivo, l\'autore vuole invitare il pubblico a un\'esperienza di introspezione e condivisione attraverso il linguaggio del cinema. Il messaggio commerciale è l\'invito a partecipare a un evento culturale e formativo a Roma, mentre l\'impatto emotivo gioca sul tema della narrazione personale (\"il racconto della nostra storia\"). La scelta di proiettare scene tratte dal celebre film *Big Fish* – un\'opera incentrata sul confine tra realtà, ricordi e mito personale – non è casuale: la pellicola fotografica che avvolge la locandina simboleggia i ricordi impressi nel tempo, invitando lo spettatore a riscoprire la propria storia di vita con meraviglia, empatia e profonda riflessione interiore.',NULL,NULL,NULL,NULL,NULL,NULL,'[]',NULL,'https://allsocialtoweb.com/public/media/facebook_1167788911803116.jpg','image',NULL,'center','0','https://www.facebook.com/MBSeminari/posts/pfbid07omDNEmhg4QH5rsXs65eHtmTTvmkaboocYn74runFDBvkZmbGWRYQafPsws1YHFXl','2025-03-19 10:41:21','2026-09-24 17:42:27','61f1f9e6362db9323a9aee5511daeec48fb8657859f1ce90ccc4d70c3d8765ea','0','Armonizzazione da riprovare: Gemini (503): This model is currently experiencing high demand. Spikes in demand are usually temporary. Please try again later.','-1','failed',NULL,'1','Gemini (503): This model is currently experiencing high demand. Spikes in demand are usually temporary. Please try again later.',NULL,'0','0');
INSERT INTO `posts` VALUES ('69','3','facebook','1147867113795296','Dovremmo imparare a “sfruttare” la sessualità in tutte le sue declinazioni… anche quelle fatte di attesa, calore, coccole, carezze e parole dolci\n\n#mauriziobottino_psy #psicologia #psicoterapeuta #psy #cambiamento #consapevolezza #coppia  #sessualità #relazionidicoppia #famiglia','L\'immagine presenta un uomo di età matura con capelli e barba grigi, che guarda direttamente verso la telecamera con un\'espressione calma, empatica e rassicurante. Indossa un maglione grigio su una camicia sui toni del blu e porta un piccolo microfono a clip sulla maglia, dettaglio che suggerisce la natura divulgativa o formativa del contenuto. Lo sfondo racchiude un ambiente intimo ed elegante, caratterizzato dai toni caldi del legno di un camino o di una mensola e da un grande quadro incorniciato, creando un\'atmosfera professionale ma al contempo accogliente e casalinga. In alto a destra compare il logo circolare \"MB Seminari\", caratterizzato dalla scritta in verde su sfondo chiaro con un bordo arancione.\n\nAl centro della composizione, sovrapposto al busto dell\'uomo, si trova un riquadro scuro semitrasparente delimitato da due dettagli geometrici colorati (un triangolo verde in alto a sinistra e uno giallo in basso a destra). All\'interno del riquadro è trascritto accuratamente il seguente testo in bianco:\n\n**\"COPPIA: la sessualità fatta di coccole e carezze\"**\n\nDal punto di vista emotivo e comunicativo, l\'autore intende trasmettere un messaggio di profonda tenerezza, intimità e comprensione riguardo alle dinamiche di coppia. L\'aspetto autorevole ma dolce del protagonista, unito all\'uso di parole chiave come \"coccole\" e \"carezze\", ridimensiona la sessualità per ricondurla a una dimensione di contatto affettivo, ascolto e vicinanza emotiva, lontana da prestazioni o stereotipi. L\'obiettivo commerciale e divulgativo è quello di intercettare un pubblico interessato alla psicologia relazionale e al benessere di coppia, promuovendo i percorsi formativi e gli incontri del brand \"MB Seminari\" attraverso un approccio delicato, rassicurante e privo di tabù.',NULL,NULL,NULL,NULL,NULL,NULL,'[]',NULL,'https://allsocialtoweb.com/public/media/facebook_1147867113795296.jpg','image',NULL,'center','0','https://www.facebook.com/reel/1188546049454711/','2025-02-21 14:10:30','2026-09-24 17:42:28','d4b16eaa27d3f7ba5b452d060a82bf4f8ebb9c63a4d28553fd7ab98d168fd704','0','Armonizzazione da riprovare: Gemini (503): This model is currently experiencing high demand. Spikes in demand are usually temporary. Please try again later.','-1','failed',NULL,'1','Gemini (503): This model is currently experiencing high demand. Spikes in demand are usually temporary. Please try again later.',NULL,'0','0');
INSERT INTO `posts` VALUES ('70','3','facebook','1144980800750594','Siamo abituati ai racconti fantastici delle favole e delle storie di cui non ci interessa poi molto… scandali, problemi sociali, ingiustizie… le storie vere sono quelle che riguardano i sentimenti, le emozioni, la sofferenza e la gioia delle persone\n\n#mauriziobottino #psicologia #psicoterapeuta #psy #cambiamento #consapevolezza #storie #emozioni #sentimenti #ascoltare #racconti','L\'immagine ritrae in primo piano un uomo maturo dal volto espressivo, con capelli e barba grigi, che indossa un maglione di colore rosso bordeaux. Il suo sguardo è fisso verso la fotocamera, trasmettendo un senso di serietà, autenticità ed empatia. Alle sue spalle si staglia un dipinto astratto ricco di consistenza e dettagli geometrici complessi, dominato da toni di blu, bianco, rosso e giallo. \n\nL\'immagine è arricchita da diversi elementi grafici: in alto a destra figura un logo circolare bordato d\'arancione recante la scritta **\"MB Seminari\"**, mentre nella parte centrale spicca un riquadro scuro semitrasparente, decorato da un triangolo verde nell\'angolo superiore sinistro e da uno giallo in quello inferiore destro. All\'interno del riquadro è ben visibile il testo scritto in bianco: **«STORIE: quelle vere, quelle di emozioni e persone»**.\n\nDal punto di vista emotivo e commerciale, l\'immagine punta a creare un legame profondo e di fiducia con chi la osserva. L\'atmosfera è intima e riflessiva, perfettamente in linea con il tema della narrazione e della formazione personale. Il messaggio chiave che l\'autore desidera veicolare è la centralità dell\'esperienza umana autentica: attraverso la promozione dei propri seminari, il brand punta a distinguersi proponendo un approccio allo storytelling lontano da artifici, focalizzato invece sulle emozioni reali, sulla verità del vissuto e sul valore intrinseco di ogni singola persona.',NULL,NULL,NULL,NULL,NULL,NULL,'[]',NULL,'https://allsocialtoweb.com/public/media/facebook_1144980800750594.jpg','image',NULL,'center','0','https://www.facebook.com/reel/1040140401467089/','2025-02-17 17:54:54','2026-09-24 17:42:29','fd4554a6fd6548b2b9e4c0be238e3169cb9247ff2723644d5ee7c19b53d33c1d','0','Armonizzazione da riprovare: Gemini (503): This model is currently experiencing high demand. Spikes in demand are usually temporary. Please try again later.','-1','failed',NULL,'1','Gemini (503): This model is currently experiencing high demand. Spikes in demand are usually temporary. Please try again later.',NULL,'0','0');
CREATE TABLE `profile_questions` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `question_key` varchar(100) NOT NULL,
  `question` text NOT NULL,
  `reason` text DEFAULT NULL,
  `answer` text DEFAULT NULL,
  `status` varchar(30) NOT NULL DEFAULT 'open',
  `created_at` datetime NOT NULL DEFAULT current_timestamp(),
  `answered_at` datetime DEFAULT NULL,
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_profile_question` (`user_id`,`question_key`),
  KEY `profile_question_user` (`user_id`,`status`),
  CONSTRAINT `fk_profile_question_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci;

INSERT INTO `profile_questions` VALUES ('3','3','editorial_focus_branding','Il nuovo sito editoriale sarà incentrato primariamente sui progetti tecnologico-artistici di Marco Mirra o dovrà includere formalmente anche i servizi di MB Seminari (Dr. Maurizio Bottino)?','Nelle sorgenti convivono canali ed evidenze sia legati a Marco Mirra (IA, musica, teatro) sia al brand MB Seminari (psicologia e percorsi d\'ascolto).','marco mirra','answered','2026-09-24 18:41:52','2026-09-24 18:42:22','2026-09-24 18:42:22');
INSERT INTO `profile_questions` VALUES ('4','3','editorial_structure_and_categories','Quali sezioni tematiche principali si desidera definire per l\'architettura del nuovo sito editoriale?','Serve ad organizzare in modo chiaro la navigazione tra i progetti tecnologico-artistici, le produzioni musicali/teatrali e gli articoli di riflessione sociale.',NULL,'open','2026-09-24 18:42:38',NULL,'2026-09-24 18:42:38');
CREATE TABLE `seo_analytics` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `record_date` date NOT NULL,
  `impressions` int(11) DEFAULT 0,
  `clicks` int(11) DEFAULT 0,
  `ctr` float DEFAULT 0,
  `position` float DEFAULT 0,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_user_seo_date` (`user_id`,`record_date`),
  CONSTRAINT `seo_analytics_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci;

CREATE TABLE `seo_search_details` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `record_date` date NOT NULL,
  `page_url` varchar(1024) NOT NULL,
  `query_text` varchar(255) NOT NULL DEFAULT '',
  `impressions` int(11) NOT NULL DEFAULT 0,
  `clicks` int(11) NOT NULL DEFAULT 0,
  `ctr` float NOT NULL DEFAULT 0,
  `position` float NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  KEY `idx_seo_details_user_date` (`user_id`,`record_date`),
  KEY `idx_seo_details_user_page` (`user_id`,`page_url`(191)),
  CONSTRAINT `seo_search_details_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci;

CREATE TABLE `site_events` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `post_id` int(11) DEFAULT NULL,
  `event_type` varchar(40) NOT NULL,
  `path` varchar(1024) NOT NULL,
  `target_url` varchar(2048) DEFAULT NULL,
  `referrer_host` varchar(255) DEFAULT NULL,
  `visitor_hash` char(64) DEFAULT NULL,
  `occurred_at` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_site_events_user_date` (`user_id`,`occurred_at`),
  KEY `idx_site_events_user_type_date` (`user_id`,`event_type`,`occurred_at`),
  KEY `post_id` (`post_id`),
  CONSTRAINT `site_events_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE,
  CONSTRAINT `site_events_ibfk_2` FOREIGN KEY (`post_id`) REFERENCES `posts` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci;

