CREATE TABLE `sites` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `title` varchar(255) DEFAULT NULL,
  `bio` text DEFAULT NULL,
  `avatar_url` text DEFAULT NULL,
  `cover_url` text DEFAULT NULL,
  `logo_url` text DEFAULT NULL,
  `brand_visual_mode` varchar(20) NOT NULL DEFAULT 'logo',
  `menu_links` text DEFAULT NULL,
  `footer_text` text DEFAULT NULL,
  `accent_color` varchar(50) DEFAULT NULL,
  `accent_secondary` varchar(50) DEFAULT NULL,
  `header_layout` varchar(50) DEFAULT 'standard',
  `custom_css` text DEFAULT NULL,
  `hero_tagline` text DEFAULT NULL,
  `cta_text` text DEFAULT NULL,
  `profile_summary` text DEFAULT NULL,
  `role_mission` text DEFAULT NULL,
  `content_strategy` text DEFAULT NULL,
  `rag_knowledge` longtext DEFAULT NULL,
  `custom_domain` varchar(255) DEFAULT NULL,
  `theme` varchar(50) DEFAULT 'classic',
  `search_visible` tinyint(4) NOT NULL DEFAULT 1,
  `seo_score` int(11) DEFAULT 0,
  `generated_layouts` longtext DEFAULT NULL,
