INSERT INTO `sites` VALUES ('1','1','Amministratore',NULL,NULL,NULL,NULL,'logo',NULL,NULL,'#d4a574',NULL,'standard','',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'dark-cinematic','1','0',NULL,'{\"design_archetype\":\"dark-cinematic\",\"font_heading\":\"Sora\",\"font_body\":\"DM Sans\",\"color_palette\":{\"background\":\"#0b0b0f\",\"surface\":\"#14141b\",\"text\":\"#f5f5f0\",\"text_muted\":\"#b7b2ab\",\"primary\":\"#d4a574\",\"secondary\":\"#2a221d\",\"primary_gradient\":\"linear-gradient(135deg, #e8bb88, #9f6a3d)\"},\"ui_style\":{\"radius\":\"20px\",\"card_shadow\":\"0 20px 60px rgba(0,0,0,0.28)\",\"glassmorphism\":true},\"layout_recipe\":{\"hero\":\"editorial\",\"nav\":\"solid\",\"cards\":\"cinematic\",\"density\":\"airy\"},\"base_models\":[\"dark-cinematic\"],\"custom_css\":\"\"}','dark-cinematic','content_editor','business',NULL,NULL,'{\"status\":\"waiting_content\",\"reason\":\"Contenuti pubblicati insufficienti per un orchestration utile\",\"published_posts\":0,\"required_posts\":8,\"updated_at\":\"2026-09-21 16:03:37\"}',NULL,NULL,'2026-09-21 16:03:37',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-09-11 01:09:36',NULL,'pulse',NULL,NULL);
INSERT INTO `sites` VALUES ('3','3','Arte, Tecnologia e Impegno Sociale','Esploro la convergenza tra Intelligenza Artificiale, produzioni teatrali e sensibilità sociale per raccontare storie di riscatto e innovazione.',NULL,'https://allsocialtoweb.com/public/media/website_67208388da8260f3f91aae7e.png',NULL,'logo','[{\"label\":\"Home\",\"url\":\"\\/\"},{\"label\":\"Teatro & Tech\",\"url\":\"\\/?tag=teatro%20e%20tecnologia\"},{\"label\":\"Arte Digitale\",\"url\":\"\\/?tag=arte%20digitale\"},{\"label\":\"Impatto Sociale\",\"url\":\"\\/?tag=riflessione%20sociale\"}]','© 2025 — Storie di innovazione, arte e sensibilità umana.','#2457d6','#2E323B','standard','.card-hover{transition:transform .3s ease, box-shadow .3s ease}.card-hover:hover{transform:translateY(-6px);box-shadow:0 15px 35px rgba(244,63,94,0.18)}','Dove l\'Intelligenza Artificiale incontra la sensibilità dell\'arte.','Unisciti alla Community',NULL,'Connettere arte digitale e valore umano attraverso l\'IA e il teatro.',NULL,NULL,NULL,'tech-clarity','0','84',NULL,'{\"design_archetype\":\"tech-clarity\",\"font_heading\":\"Plus Jakarta Sans\",\"font_body\":\"Inter\",\"color_palette\":{\"background\":\"#f1f5ff\",\"surface\":\"#ffffff\",\"text\":\"#14213d\",\"text_muted\":\"#5c6983\",\"primary\":\"#2457d6\",\"secondary\":\"#d9e4ff\",\"primary_gradient\":\"linear-gradient(135deg,#4c7af0,#173fa7)\"},\"ui_style\":{\"radius\":\"16px\",\"card_shadow\":\"0 10px 30px rgba(15,23,42,.08)\",\"glassmorphism\":false},\"layout_recipe\":{\"structure\":\"classic\",\"hero\":\"product\",\"nav\":\"expanded\",\"cards\":\"bold\",\"density\":\"balanced\",\"section_order\":[\"hero\",\"latest\",\"topics\",\"info\"],\"hidden_sections\":[]},\"base_models\":[\"tech-clarity\"],\"custom_css\":\".card-hover{transition:transform .3s ease, box-shadow .3s ease}.card-hover:hover{transform:translateY(-6px);box-shadow:0 15px 35px rgba(244,63,94,0.18)}\",\"custom_sections\":[]}','tech-clarity','content_editor','business','{\"site_objective\":\"Posizionare il sito come hub italiano di riferimento per la convergenza tra intelligenza artificiale, produzioni teatrali\\/musicali e impatto sociale.\",\"audience\":\"Innovatori culturali, professionisti del teatro e della musica, appassionati di tecnologia etica, formatori ed educatori.\",\"positioning\":\"L\'intersezione autorevole dove l\'innovazione digitale dell\'IA incontra la sensibilità artistica e il riscatto sociale.\",\"tone_rules\":[\"Divulgativo ma tecnicamente rigoroso nell\'ambito AI e Creative Tech\",\"Orientato all\'impatto etico e al valore umano di ogni innovazione\",\"Narrativo e coinvolgente quando si trattano storie di riscatto e arte\"],\"content_pillars\":[\"IA & Creazione Artistica (Musica e Suono)\",\"Innovazione Teatrale e Produzione Scenica\",\"Tecnologia, Etica e Politiche Sociali\",\"Storie di Riscatto e Made in Italy\"],\"topic_clusters\":[\"Sonificazione ed Esperimenti Multimediali (SonificART)\",\"Integrazione Tecnologica nello Spettacolo dal Vivo\",\"IA, Genitorialità ed Educazione Digitale\",\"Musica Sociale e Sensibilizzazione Culturale\"],\"seo_entities\":[\"Marco Mirra\",\"Intelligenza Artificiale\",\"SonificART\",\"Teatro Brancaccio\",\"Belle Capocce\"],\"continuity_rules\":[\"Incrociare sempre la dimensione tecnologica con un risvolto sociale o etico\",\"Inserire link interni incrociati tra progetti pratici e riflessioni teoriche\",\"Garantire una struttura ad albero con pagine pilastro verticali ben definite\"],\"indexing_priorities\":[\"Creazione delle pagine cornerstone tematiche per canalizzare la link juice\",\"Consolidamento del cluster \'Arte e IA\' attorno al progetto SonificART\",\"Ottimizzazione dei metadati e della struttura interna dei post con seo_score inferiore a 80\"]}','{\"covered_topics\":[\"Sonificazione delle immagini e algoritmi creativi con IA\",\"Violenza sulle donne e musica per il sociale\",\"Teatro e innovazione tecnologica al Teatro Brancaccio\",\"Riflessione critica su politiche sociali e consapevolezza\",\"IA per la genitorialità e il confronto tra intelligenza umana ed artificiale\"],\"content_gaps\":[\"Guida definitiva alla sonificazione e musica generativa tramite IA\",\"Manifesto del Teatro Digitale: integrare tecnologia ed emozione sul palco\",\"Analisi etica e quadro normativo sull\'uso dell\'IA nella formazione e in famiglia\"],\"internal_link_hubs\":[\"Hub: Arte Digitale e Intelligenza Artificiale\",\"Hub: Innovazione Teatrale e Spettacolo dal Vivo\",\"Hub: Tecnologie per il Sociale e Crescita Personale\"],\"cornerstone_pages\":[\"Guida Completa alla Sonificazione e Generazione Sonora con IA\",\"Teatro e Tecnologia: Il Futuro delle Produzioni Sceniche\",\"Intelligenza Umana e Artificiale: Prospettive Etiche per la Società\"]}','{\"featured_post_id\":24,\"continuity_summary\":\"Il sito presenta una solida base narrativa incentrata sul ruolo dell\'IA nella musica, nel teatro e nel sociale. Tuttavia, la produzione attuale tende a disperdersi tra temi d\'attualità politica e progetti artistici senza una chiara gerarchia di linking interno. Risulta fondamentale strutturare le pagine cornerstone per raggruppare i post recenti e rafforzare l\'autorevolezza del dominio su Google.\",\"next_actions\":[\"Creare la pagina cornerstone \'Arte Digitale e IA\' e collegarvi SonificART (ID 24) e la produzione musicale (ID 39)\",\"Ottimizzare il post \'Una storia d\'eccellenza\' (ID 21, SEO 78) migliorando titoli H2 e metadati per portarlo a score >85\",\"Strutturare il cluster \'Teatro e Tecnologia\' collegando il post sul Teatro Brancaccio (ID 23) a future schede tecniche\",\"Unificare le riflessioni su IA Umana vs Artificiale (ID 45 e ID 35) sotto un unico hub informativo etico-sociale\"],\"next_topics\":[\"Metodologie applicate di Sonificazione dei dati e immagini con IA\",\"Accessibilità teatrale grazie a sensori e intelligenza artificiale\",\"L\'etica degli algoritmi nella produzione musicale a sfondo sociale\",\"Guida pratica all\'educazione digitale e IA per genitori ed educatori\",\"Analisi comparative tra modelli di intelligenza artificiale e creatività umana\"],\"seo_risks\":[\"Cannibalizzazione della parola chiave \'Intelligenza Artificiale\' presente in troppi post senza una pagina pilastro definita\",\"Frammentazione tematica tra articoli di opinione socio-politica e articoli verticali di tecnologia musicale\"],\"status\":\"needs_cornerstones\"}','{\"enabled\":true,\"auto_run\":true,\"min_posts\":8,\"strict_indexing_mode\":true}',NULL,'2026-09-21 16:03:33',NULL,NULL,'{\"business_type\":\"Person\",\"summary\":\"Marco Mirra è un AI Creative Technologist attivo nell\'intersezione tra Intelligenza Artificiale, produzioni teatrali, musica e sensibilizzazione sociale.\",\"location\":\"Non specificata nei dati\",\"services\":[{\"name\":\"Sonificazione di immagini (SonificART)\",\"description\":\"Trasformazione di immagini in composizioni sonore originali tramite l\'applicazione web SonificART basata su algoritmi deterministici e IA.\",\"evidence_post_ids\":[24]},{\"name\":\"Produzioni musicali e videoclip con IA\",\"description\":\"Composizione di brani musicali, orchestrazione, mastering e creazione visiva di videoclip mediante supporto di strumenti IA.\",\"evidence_post_ids\":[20,39,50]},{\"name\":\"Integrazione tra teatro e tecnologia\",\"description\":\"Progettazione e studio dell\'integrazione di tecnologie digitali nelle produzioni teatrali per valorizzare l\'espressività artistica.\",\"evidence_post_ids\":[23]},{\"name\":\"Sviluppo di software basati su IA\",\"description\":\"Creazione di applicativi software che integrano differenti modelli di IA per l\'analisi e la chiarificazione di tematiche complesse.\",\"evidence_post_ids\":[35]}],\"audience\":\"Famiglie, associazioni, operatori del settore teatrale e artistico, e persone interessate all\'impatto sociale ed educativo delle tecnologie digitali.\",\"facts\":[{\"text\":\"Marco Mirra opera come AI Creative Technologist focalizzato su arte digitale, musica e impatto sociale.\",\"evidence_post_ids\":[20,24]},{\"text\":\"È stata creata l\'applicazione SonificART per convertire immagini in suoni usando un metodo deterministico e IA.\",\"evidence_post_ids\":[24]},{\"text\":\"È stato realizzato un brano musicale di sensibilizzazione contro la violenza sulle donne con supporto dell\'IA per orchestrazione e soggetti video.\",\"evidence_post_ids\":[20]},{\"text\":\"È in corso uno studio sull\'integrazione tra tecnologia e performance al Teatro Brancaccio.\",\"evidence_post_ids\":[23]},{\"text\":\"È stato tenuto un intervento con l\'Associazione Nazionale Famiglie Numerose ed è prevista la pubblicazione di un libro orientato alla tutela delle future generazioni nell\'era dell\'IA.\",\"evidence_post_ids\":[28]},{\"text\":\"È stato sviluppato un software basato su modelli IA per analizzare i dati del Referendum del 22 e 23 Marzo.\",\"evidence_post_ids\":[35]},{\"text\":\"È stato avviato il progetto \'Belle Capocce\' sulla valorizzazione dell\'intelligenza umana rispetto all\'IA.\",\"evidence_post_ids\":[45]}],\"questions_to_confirm\":[\"Qual è l\'indirizzo della sede legale o l\'ubicazione fisica principale dell\'attività?\",\"Quali sono i recapiti diretti di contatto (email e telefono ufficiali)?\",\"Qual è il titolo definitivo, la data di uscita e l\'editore del libro annunciato?\",\"Quali sono i costi o le modalità di vendita delle applicazioni e dei servizi offerti?\"],\"pages\":[{\"slug\":\"chi-siamo\",\"title\":\"Chi Siamo - Marco Mirra e la visione tra Arte e IA\",\"meta_description\":\"Scopri la missione di Marco Mirra: unire Intelligenza Artificiale, musica, teatro e impegno sociale per raccontare storie di valore.\",\"intro\":\"Marco Mirra unisce l\'innovazione dell\'Intelligenza Artificiale con l\'espressività teatrale e la sensibilità verso le tematiche sociali.\",\"sections\":[{\"heading\":\"Missione e approccio\",\"body\":\"La visione del progetto si fonda sul connettere arte digitale e valore umano. Anziché seguire i semplici trend di mercato, l\'obiettivo è riconoscere i pattern tecnologici e sociali per raccontare storie di riscatto e di innovazione.\",\"evidence_post_ids\":[20,24]},{\"heading\":\"Iniziative e divulgazione\",\"body\":\"L\'impegno si estende anche all\'ambito educativo e culturale, come dimostrato dai confronti con l\'Associazione Nazionale Famiglie Numerose e dai progetti editoriali orientati a fornire strumenti di riflessione e azione per le generazioni future.\",\"evidence_post_ids\":[28]}],\"faq\":[]},{\"slug\":\"cosa-offriamo\",\"title\":\"Cosa Offriamo - Soluzioni e Progetti Tecnologici e Artistici\",\"meta_description\":\"Esplora i progetti e le applicazioni create con l\'IA: da SonificART all\'integrazione tecnologica per il teatro e la musica.\",\"intro\":\"I progetti realizzati integrano software di Intelligenza Artificiale, composizioni musicali e tecnologie applicate al teatro.\",\"sections\":[{\"heading\":\"Applicazioni Web e Sonificazione\",\"body\":\"Sviluppo di soluzioni come SonificART.com, una piattaforma che applica algoritmi deterministici e modelli neurale-IA per tradurre elementi visivi e immagini in opere sonore.\",\"evidence_post_ids\":[24]},{\"heading\":\"Sviluppo Software e Analisi IA\",\"body\":\"Creazione di software personalizzati capaci di mettere a confronto diverse Intelligenze Artificiali per analizzare e chiarire quesiti complessi, come quelli referendari.\",\"evidence_post_ids\":[35]},{\"heading\":\"Produzioni Musicali e Spettacolo Teatrale\",\"body\":\"Realizzazione di brani musicali, videoclip e progetti di integrazione tecnologica su palco, pensati per amplificare il coinvolgimento emotivo negli spettacoli dal vivo.\",\"evidence_post_ids\":[20,23,39,50]}],\"faq\":[]},{\"slug\":\"per-chi\",\"title\":\"Per Chi - Destinatari dei Progetti e delle Iniziative\",\"meta_description\":\"I progetti si rivolgono ad associazioni, famiglie, mondo dello spettacolo e a chi cerca un approccio consapevole all\'IA.\",\"intro\":\"L\'attività si rivolge a realtà sociali, al settore culturale e artistico, e alla comunità interessata all\'uso consapevole della tecnologia.\",\"sections\":[{\"heading\":\"Famiglie ed enti del terzo settore\",\"body\":\"Supporto e momenti di confronto rivolti ad associazioni di famiglie e genitori per comprendere le dinamiche delle nuove tecnologie e tutelare la crescita dei giovani.\",\"evidence_post_ids\":[28]},{\"heading\":\"Mondo dello spettacolo e produzioni artistiche\",\"body\":\"Sperimentazioni e soluzioni dedicate ad artisti, teatri e produzioni che intendo esplorare la convergenza tra performance live e tecnologie digitali.\",\"evidence_post_ids\":[23]}],\"faq\":[]},{\"slug\":\"domande-frequenti\",\"title\":\"Domande Frequenti - Progetti, IA e Musica\",\"meta_description\":\"Risposte alle domande comuni sui progetti di sonificazione, musica con IA, teatro tecnologico e divulgazione.\",\"intro\":\"Raccolta di informazioni pratiche sulle tecnologie e sulle produzioni sviluppate.\",\"sections\":[],\"faq\":[{\"question\":\"Cos\'è SonificART?\",\"answer\":\"SonificART è un\'applicazione web sviluppata per tradurre le immagini in composizioni musicali e sonore utilizzando un metodo deterministico e algoritmi di IA.\",\"evidence_post_ids\":[24]},{\"question\":\"Come viene utilizzata l\'IA nelle produzioni musicali e video?\",\"answer\":\"L\'IA viene usata come strumento di supporto per fasi quali orchestrazione, mastering e generazione di elementi visivi nei videoclip, affiancandosi alla scrittura e composizione umana.\",\"evidence_post_ids\":[20]},{\"question\":\"In cosa consiste l\'integrazione tra teatro e tecnologia?\",\"answer\":\"Consiste nello studio di soluzioni tecnologiche applicate alle scenografie o alla performance dal vivo per intensificare l\'impatto emotivo trasmesso al pubblico.\",\"evidence_post_ids\":[23]}]}],\"generated_by\":\"ai_with_evidence\"}','1e846e62f227b0f645ea85673716b0be05a580ca49fa58c01fc454d49a9f78f1','2026-09-24 17:46:56','{\"presence_mode\":\"existing_site\",\"official_site_url\":\"https://www.marcomirra.it\",\"business_profile_url\":\"\",\"primary_topic\":\"Sonificazione AI e tecnologie innovative\",\"service_areas\":[\"Italia\"],\"reciprocal_link_confirmed\":true,\"phone\":\"\",\"whatsapp\":\"\",\"email\":\"info@marcomirra.it\",\"search_console_choice\":\"connected\"}','2026-09-19 11:09:15',NULL,'2026-09-24 17:42:29','2026-09-19 09:02:21','{\"source\":\"profile_analyzer\",\"tone\":\"Riflessivo, divulgativo, impegnato e innovativo\",\"topic_clusters\":[\"Intelligenza Artificiale applicata alla musica e all\'arte\",\"Integrazione tra teatro e tecnologie digitali\",\"Riflessioni sociali, culturali e politiche pubbliche\",\"Formazione, pensiero critico e valori educativi\"],\"audiences\":[\"Appassionati di arte digitale, intelligenza artificiale e innovazione tecnologica\",\"Operatori e pubblico del settore teatrale e musicale\",\"Educatori, famiglie e giovani\",\"Comunità locale e parrocchiale di Roma\"],\"generated_at\":\"2026-09-24 18:42:38\"}','pulse',NULL,NULL);
CREATE TABLE `social_connections` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `platform` varchar(50) NOT NULL,
  `platform_uid` varchar(255) DEFAULT NULL,
  `handle` varchar(255) DEFAULT NULL,
  `access_token` text NOT NULL,
  `refresh_token` text DEFAULT NULL,
  `expires_at` datetime DEFAULT NULL,
  `connected_at` datetime DEFAULT current_timestamp(),
  `active` tinyint(4) DEFAULT 1,
  `since_date` date DEFAULT NULL,
  `auto_publish` tinyint(4) DEFAULT 1,
  `auto_sync` tinyint(4) DEFAULT 1,
  `max_posts` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_user_platform` (`user_id`,`platform`),
  CONSTRAINT `social_connections_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci;

CREATE TABLE `social_sources` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `user_id` int(11) NOT NULL,
  `platform` varchar(50) NOT NULL,
  `label` varchar(255) DEFAULT NULL,
  `url` text NOT NULL,
  `topic_summary` text DEFAULT NULL,
  `active` tinyint(4) DEFAULT 1,
  `since_date` date DEFAULT NULL,
  `auto_publish` tinyint(4) DEFAULT 1,
  `auto_sync` tinyint(4) DEFAULT 1,
  `max_posts` int(11) DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  `last_scan_note` varchar(255) DEFAULT NULL,
  `last_scan_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_user_source` (`user_id`,`platform`,`url`(191)),
  CONSTRAINT `social_sources_ibfk_1` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci;

