CREATE TABLE `user_content_profiles` (
  `user_id` int(11) NOT NULL,
  `status` varchar(30) NOT NULL DEFAULT 'pending',
  `display_name` varchar(255) DEFAULT NULL,
  `activity_type` varchar(255) DEFAULT NULL,
  `summary` text DEFAULT NULL,
  `audiences` longtext DEFAULT NULL,
  `topics` longtext DEFAULT NULL,
  `tone` varchar(255) DEFAULT NULL,
  `goals` longtext DEFAULT NULL,
  `locations` longtext DEFAULT NULL,
  `offers` longtext DEFAULT NULL,
  `evidence` longtext DEFAULT NULL,
  `confidence` decimal(5,4) NOT NULL DEFAULT 0.0000,
  `source_count` int(11) NOT NULL DEFAULT 0,
  `content_count` int(11) NOT NULL DEFAULT 0,
  `error_message` text DEFAULT NULL,
  `generated_at` datetime DEFAULT NULL,
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`user_id`),
  CONSTRAINT `fk_content_profile_user` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci;

INSERT INTO `user_content_profiles` VALUES ('3','needs_answers','Marco Mirra','Artista e innovatore tecnologico','Marco Mirra è un artista e progettista specializzato nell\'integrazione tra intelligenza artificiale, musica, teatro e impatto sociale. Sviluppa software e progetti artistici (come la piattaforma SonificART, brani musicali e iniziative teatrali) affiancandoli a riflessioni culturali, educative e civili.','[\"Appassionati di arte digitale, intelligenza artificiale e innovazione tecnologica\",\"Operatori e pubblico del settore teatrale e musicale\",\"Educatori, famiglie e giovani\",\"Comunità locale e parrocchiale di Roma\"]','[\"Intelligenza Artificiale applicata alla musica e all\'arte\",\"Integrazione tra teatro e tecnologie digitali\",\"Riflessioni sociali, culturali e politiche pubbliche\",\"Formazione, pensiero critico e valori educativi\"]','Riflessivo, divulgativo, impegnato e innovativo','[\"Unire creatività umana e intelligenza artificiale in progetti artistici ad alto impatto sociale\",\"Promuovere il pensiero critico di fronte alle nuove tecnologie e alla manipolazione visiva\",\"Condividere competenze ed esperienze con le nuove generazioni\"]','[\"Roma\",\"Italia\"]','[\"Piattaforma SonificART per la sonificazione delle immagini tramite IA\",\"Produzioni musicali e videoclip con integrazione di IA\",\"Progetti di innovazione tecnologica applicata al teatro\",\"Software e strumenti di analisi basati su IA\",\"Incontri di divulgazione, catechesi e riflessione socio-culturale\"]','[{\"content_id\":24,\"reason\":\"Descrive la creazione di SonificART, applicazione web per trasformare immagini in composizioni sonore con l\'IA.\"},{\"content_id\":20,\"reason\":\"Mostra la produzione di un brano musicale realizzato con l\'IA per sensibilizzare contro la violenza sulle donne.\"},{\"content_id\":23,\"reason\":\"Testimonia lo studio e la progettazione sull\'integrazione tra teatro e tecnologia al Teatro Brancaccio.\"},{\"content_id\":28,\"reason\":\"Evidenzia la collaborazione con l\'Associazione Famiglie Numerose e la stesura di un libro sull\'IA per le nuove generazioni.\"},{\"content_id\":35,\"reason\":\"Riporta la creazione di un software basato sull\'IA per analizzare e confrontare opinioni in occasione del referendum.\"},{\"content_id\":36,\"reason\":\"Documenta le attività di catechesi e riflessione spirituale e comunitaria presso la Parrocchia S. Achille a Roma.\"},{\"content_id\":45,\"reason\":\"Presenta il progetto \'Belle Capocce\' focalizzato sulla valorizzazione del potenziale umano rispetto all\'IA.\"},{\"content_id\":50,\"reason\":\"Conferma la produzione artistica musicale e visiva con il videoclip \'Sulla Fune Della Vita\'.\"}]','0.9500','4','42',NULL,'2026-09-24 18:42:38','2026-09-24 18:42:38');
CREATE TABLE `user_economics` (
  `user_id` int(11) NOT NULL,
  `monthly_revenue` decimal(12,2) NOT NULL DEFAULT 0.00,
  `hosting_cost` decimal(12,2) NOT NULL DEFAULT 0.00,
  `other_cost` decimal(12,2) NOT NULL DEFAULT 0.00,
  `notes` text DEFAULT NULL,
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci;

CREATE TABLE `users` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `email` varchar(255) NOT NULL,
  `password` varchar(255) NOT NULL,
  `name` varchar(255) DEFAULT NULL,
  `slug` varchar(100) DEFAULT NULL,
  `role` varchar(20) DEFAULT 'user',
  `plan` varchar(20) DEFAULT 'free',
  `token_version` int(11) NOT NULL DEFAULT 0,
  `created_at` datetime DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `email` (`email`),
  UNIQUE KEY `slug` (`slug`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci;

